using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

// Akiba: a few blocks of Akihabara at night, everything wearing photographs (generated by
// Tools/gen_akiba_photos.py, the Mallbat look) on low-poly shapes, drawn a little rough in the PlayStation
// style. One short avenue, a canyon of neon-covered buildings with a plaza in the middle, and floating over
// the middle of it, chunks of the city torn loose (bits of road, pavement, shrine gardens, rooftops)
// hanging in the air at every height.
//
// It's built so that wherever you are there's always a way on to anywhere else: escalators (one floats up
// to an island), glass lifts up the four towers, walkways along the fronts with moving footbridges across,
// launch pads (the glowing dots show where they throw you), vents, trampolines, short rails, jumps, fast
// buses on the avenue (with a kicker on the roof), slow flying buses that stop at the islands and the
// roofs, the train across the north end, and flying cars: land on one and fly it for five seconds before it
// falls apart. Every surface and every way between them is recorded (SkateWorldBuilder.AkibaLinks.cs), and
// the test runs ride every one of them.
public static partial class SkateWorldBuilder
{
    public const string AkibaPath = "Assets/Scenes/Akiba.unity";
    const string AkibaTex = "Assets/Akiba/Textures", AkibaMats = "Assets/Akiba/Materials", AkibaPhotos = "Assets/Akiba/Photos";

    // the layout: the avenue runs along z
    const float AkL = 120f;                              // the canyon runs z = -120..120, closed off by a building at each end
    const float AkRoad = 8f;                             // the road, x = -8..8
    const float AkFront = 28f;                           // the building fronts along the avenue...
    const float AkPlazaFront = 46f, AkPlazaHalf = 36f;   // ...and round the plaza in the middle (z = -36..36)
    const float AkBack = 60f;                            // the backs of the buildings: an alley behind, then the skyline
    const float AkLaneCar = 2.2f, AkLaneBus = 5.8f;
    const float AkWalkY = 7f, AkBalconyY = 8f;
    const float AkViaductY = 11f, AkViaductZ = 100f;
    const float AkStopY = 3.5f;                          // the bus stops' platforms: level with a bus roof

    static readonly Dictionary<string, PSXKit> akKits = new Dictionary<string, PSXKit>();
    static readonly Dictionary<string, Material> akMats = new Dictionary<string, Material>();
    static System.Random ark;
    static Transform akRoot, akCol;
    static readonly List<(Rect lot, float h, float side)> akLots = new List<(Rect, float, float)>();
    static readonly List<Bounds> akKeepOut = new List<Bounds>();   // signs, stalls and balconies keep out of these
    static int akSouthWalk, akNorthWalk, akBalconyE, akBalconyW, akRailway;

    static float AR(float a, float b) { return a + (float)ark.NextDouble() * (b - a); }
    static int AI(int a, int b) { return ark.Next(a, b); }

    static float AkFrontAt(float z) { return Mathf.Abs(z) <= AkPlazaHalf ? AkPlazaFront : AkFront; }
    static float AkFloor(float x, float z)
    {
        float ax = Mathf.Abs(x);
        return ax > AkRoad && ax < AkFrontAt(z) + 0.5f && Mathf.Abs(z) < AkL ? Kerb : 0f;
    }

    static bool Kept(Bounds b)
    {
        foreach (var k in akKeepOut) if (k.Intersects(b)) return true;
        return false;
    }

    static void ImportAkibaTextures()
    {
        AssetDatabase.Refresh();
        var files = new List<string>(Directory.GetFiles(AkibaTex, "*.png"));
        if (Directory.Exists(AkibaPhotos)) files.AddRange(Directory.GetFiles(AkibaPhotos, "*.png"));
        foreach (var path in files)
        {
            var imp = AssetImporter.GetAtPath(path.Replace('\\', '/')) as TextureImporter;
            if (imp == null) continue;
            var filter = path.Contains("Photos") ? FilterMode.Bilinear : FilterMode.Point;   // photos a touch softer
            if (imp.filterMode == filter && imp.textureCompression == TextureImporterCompression.Uncompressed && imp.maxTextureSize == 512) continue;
            imp.filterMode = filter;
            imp.wrapMode = TextureWrapMode.Repeat;
            imp.mipmapEnabled = true;
            imp.textureCompression = TextureImporterCompression.Uncompressed;
            imp.alphaIsTransparency = false;
            imp.maxTextureSize = 512;
            imp.SaveAndReimport();
        }
    }

    // the generated photo standing in for a texture name, if there is one
    static string Photo(string tex)
    {
        string p = tex;
        int n = 0;
        int us = tex.LastIndexOf('_');
        if (us > 0) int.TryParse(tex.Substring(us + 1), out n);
        switch (tex)
        {
            case "asphalt": p = "photo_asphalt"; break;
            case "pavement": p = "photo_pavement"; break;
            case "tactile": p = "photo_tactile"; break;
            case "concrete": p = "photo_concrete"; break;
            case "roof": p = "photo_roof"; break;
            case "shutter": p = "photo_shutter"; break;
            case "metal": p = "photo_metal"; break;
            case "posters": p = "photo_posters"; break;
            case "vending": p = "photo_vending"; break;
            case "gacha": p = "photo_gacha"; break;
            case "train_side": p = "photo_train"; break;
            case "earth": p = "photo_earth"; break;
            case "grass": p = "photo_grass"; break;
            case "escalator": p = "photo_escalator"; break;
            case "plaza": p = "photo_plaza"; break;
            case "screen": p = "photo_screen"; break;
            default:
                if (tex.StartsWith("graffiti_")) p = "photo_graffiti_" + (n % 4);
                else if (tex.StartsWith("facade_")) p = "fac_akiba_" + (n % 6);
                else if (tex.StartsWith("shop_")) p = "shop_" + (n % 8);
                else if (tex.StartsWith("sign_v_")) p = "vsign_" + (n % 8);
                else if (tex.StartsWith("sign_h_")) p = "hsign_" + (n % 6);
                else if (tex.StartsWith("billboard_")) p = "ad_" + (n % 10);
                break;
        }
        return File.Exists(AkibaPhotos + "/" + p + ".png") ? p : null;
    }

    // style: "" lit by the moon, "e" full bright, "f" full bright and flickering, "s" full bright and scrolling,
    // "x"/"y" full bright and scrolling along (escalators)
    static Material AkMat(string tex, string style)
    {
        string key = tex + "|" + style;
        Material m;
        if (akMats.TryGetValue(key, out m)) return m;
        Directory.CreateDirectory(AkibaMats);
        string path = AkibaMats + "/" + tex + (style == "" ? "" : "_" + style) + ".mat";
        m = AssetDatabase.LoadAssetAtPath<Material>(path);
        var sh = Shader.Find("3daigamesolo/PSX/Textured");
        if (m == null) { m = new Material(sh); AssetDatabase.CreateAsset(m, path); }
        m.shader = sh;
        string photo = Photo(tex);
        string file = photo != null ? AkibaPhotos + "/" + photo + ".png" : AkibaTex + "/" + tex + ".png";
        if (!File.Exists(file)) file = AkibaTex + "/white.png";
        m.SetTexture("_MainTex", AssetDatabase.LoadAssetAtPath<Texture2D>(file));
        m.SetFloat("_Emission", style == "" ? 0f : 1f);
        // "s" scrolls sideways (LED tickers); "x" and "y" scroll along v, one way or the other (escalator steps, moving walkways)
        m.SetVector("_Scroll", style == "s" ? new Vector4(0.12f, 0f, 0f, 0f) : style == "x" ? new Vector4(0f, -4f, 0f, 0f) : style == "y" ? new Vector4(0f, 4f, 0f, 0f) : Vector4.zero);
        m.SetVector("_Flicker", style == "f" ? new Vector4(AR(0.3f, 1.4f), AR(0.6f, 0.92f), AR(0.25f, 0.5f), 0f) : new Vector4(0f, 1f, 1f, 0f));
        m.SetFloat("_Cutoff", 0f);
        EditorUtility.SetDirty(m);
        akMats[key] = m;
        return m;
    }

    static PSXKit AK(string tex, string style = "")
    {
        string key = tex + "|" + style;
        PSXKit k;
        if (!akKits.TryGetValue(key, out k)) { k = new PSXKit(); akKits[key] = k; AkMat(tex, style); }
        return k;
    }

    static void FlushAkiba(Transform parent)
    {
        foreach (var kv in akKits)
        {
            if (kv.Value.Empty) continue;
            var mesh = kv.Value.Build(kv.Key.Replace('|', '_'));
            SaveFeatureMesh(mesh);
            var go = new GameObject(kv.Key, typeof(MeshFilter), typeof(MeshRenderer));
            go.transform.SetParent(parent, false);
            go.GetComponent<MeshFilter>().sharedMesh = mesh;
            go.GetComponent<MeshRenderer>().sharedMaterial = akMats[kv.Key];
        }
        akKits.Clear();
    }

    static void AkBox(Vector3 c, Vector3 size, Quaternion? rot = null) { AddBox(akCol, "Solid", c, size, rot); }

    // for a panel facing n: the direction that's right to someone looking at it (so its picture reads the right way round)
    static Vector3 Rt(Vector3 n) { return Vector3.Cross(n, Vector3.up); }

    // a flat wall from p0 along `along` for `w` metres, from y0 to y1, facing `n`, tiled every tu x tv metres
    static void Wall(PSXKit k, Vector3 p0, Vector3 along, float w, float y0, float y1, Vector3 n, float tu, float tv, float v0 = 0f)
    {
        Vector3 a = new Vector3(p0.x, y0, p0.z), b = a + along * w;
        float va = (y0 - v0) / tv, vb = (y1 - v0) / tv;
        k.Quad(a, new Vector3(a.x, y1, a.z), new Vector3(b.x, y1, b.z), b,
               new Vector2(0f, va), new Vector2(0f, vb), new Vector2(w / tu, vb), new Vector2(w / tu, va), n);
    }

    // a wall facing n, `w` wide centred on `centre`, its picture left to right as you look at it
    static void FrontWall(PSXKit k, Vector3 centre, Vector3 n, float w, float y0, float y1, float tu, float tv, float v0 = 0f)
    {
        Vector3 along = Rt(n);
        Wall(k, new Vector3(centre.x, 0f, centre.z) - along * (w / 2f), along, w, y0, y1, n, tu, tv, v0);
    }

    // a kicker you can hit from either side: two back to back, lips meeting in the middle
    static void Hump(string name, Vector3 at, Vector3 dir, float radius, float degrees, float width, Color32 side)
    {
        float len = radius * Mathf.Sin(degrees * Mathf.Deg2Rad);
        Kicker(name, Matrix4x4.TRS(at, Quaternion.LookRotation(dir), Vector3.one), radius, degrees, width, side);
        Kicker(name, Matrix4x4.TRS(at + dir * len * 2f, Quaternion.LookRotation(-dir), Vector3.one), radius, degrees, width, side);
    }

    // a wedge ramp: from the ground at `at` rising along `dir` to `height` over `length`, `width` wide
    static void Wedge(string tex, Vector3 at, Vector3 dir, float length, float height, float width)
    {
        Vector3 top = at + dir * length + Vector3.up * height;
        Vector3 side = Rt(dir) * (width / 2f);
        var k = AK(tex);
        Vector2 u0 = new Vector2(0f, 0f), u1 = new Vector2(0f, length / 3f), u2 = new Vector2(width / 3f, length / 3f), u3 = new Vector2(width / 3f, 0f);
        Vector3 up = Vector3.Cross(dir, Rt(dir)).normalized; if (up.y < 0f) up = -up;
        k.Quad(at - side, top - side, top + side, at + side, u0, u1, u2, u3, Vector3.Cross(top - at, side));
        Vector3 back = at + dir * length;
        k.Quad(back - side, back - side + Vector3.up * height, back + side + Vector3.up * height, back + side, u0, u1, u2, u3, dir);
        foreach (var s in new[] { -1f, 1f })
            k.Quad(at + side * s, top + side * s, back + side * s, back + side * s, u0, u1, u2, u3, Rt(dir) * s);
        float slope = Mathf.Atan2(height, length) * Mathf.Rad2Deg, len = Mathf.Sqrt(height * height + length * length);
        Quaternion q = Quaternion.LookRotation(dir) * Quaternion.Euler(-slope, 0f, 0f);
        AkBox((at + top) / 2f + q * Vector3.down * 0.15f, new Vector3(width, 0.3f, len), q);
        AkBox(back + Vector3.up * height / 2f - dir * 0.15f, new Vector3(width, height, 0.3f), Quaternion.LookRotation(dir));
    }

    static Vector3[] Spline(Vector3[] ctrl, int perSeg)
    {
        var pts = new List<Vector3>();
        for (int i = 0; i < ctrl.Length - 1; i++)
        {
            Vector3 p0 = ctrl[Mathf.Max(0, i - 1)], p1 = ctrl[i], p2 = ctrl[i + 1], p3 = ctrl[Mathf.Min(ctrl.Length - 1, i + 2)];
            for (int k = 0; k < perSeg; k++)
            {
                float t = k / (float)perSeg, t2 = t * t, t3 = t2 * t;
                pts.Add(0.5f * (2f * p1 + (-p0 + p2) * t + (2f * p0 - 5f * p1 + 4f * p2 - p3) * t2 + (-p0 + 3f * p1 - 3f * p2 + p3) * t3));
            }
        }
        pts.Add(ctrl[ctrl.Length - 1]);
        return pts.ToArray();
    }

    // a glowing arrow on the ground that shoots you off the way it points
    static void BoostArrow(Vector3 at, Vector3 dir, float speed)
    {
        dir = new Vector3(dir.x, 0f, dir.z).normalized;
        Vector3 side = Rt(dir);
        var k = AK("white", "e");
        k.Box(at + Vector3.up * 0.03f, new Vector3(2.4f, 0.04f, 3.2f), Quaternion.LookRotation(dir), 1f, 1f, new Color32(20, 40, 70, 255));
        for (int i = 0; i < 3; i++)
        {
            Vector3 c = at + dir * (i - 1f) * 0.95f + Vector3.up * 0.07f;
            // a chevron: two bars meeting at the front
            foreach (var s in new[] { -1f, 1f })
                k.Box(c + side * s * 0.45f, new Vector3(0.22f, 0.04f, 1.1f), Quaternion.LookRotation(dir + side * s * 0.9f), 1f, 1f, new Color32(60, 240, 255, 255));
        }
        var col = AddBox(akCol, "Boost pad", at + Vector3.up * 0.03f, new Vector3(2.4f, 0.06f, 3.2f), Quaternion.LookRotation(dir));
        var pad = col.gameObject.AddComponent<BoostPad>();
        pad.direction = dir; pad.speed = speed;
    }

    // a giant capsule toy, half clear and half coloured: land on it and it bounces you high
    static void Capsule(Vector3 at, float r)
    {
        var k = new SkateMeshKit();
        Color32 col = new[] { new Color32(255, 70, 160, 255), new Color32(60, 230, 255, 255), new Color32(255, 214, 40, 255), new Color32(140, 255, 120, 255) }[AI(0, 4)];
        Vector3 c = at + Vector3.up * r * 0.85f;
        k.Ellipsoid(c, new Vector3(r, r * 0.85f, r), Quaternion.identity, 14, 10, col);
        k.Box(c, new Vector3(r * 2.02f, 0.12f, r * 2.02f), Quaternion.identity, new Color32(255, 255, 255, 255));
        k.Ellipsoid(c + Vector3.up * r * 0.25f + new Vector3(-r * 0.3f, 0f, -r * 0.3f), Vector3.one * r * 0.18f, Quaternion.identity, 8, 5, new Color32(255, 255, 255, 255));
        var mesh = k.Build("Capsule");
        SaveFeatureMesh(mesh);
        MeshObject("Capsule", akRoot, mesh, AkMat("white", "e"), outlineMat);
        var sc = new GameObject("Capsule").AddComponent<SphereCollider>();
        sc.transform.SetParent(akCol, false);
        sc.transform.position = c; sc.radius = r * 0.9f;
        sc.gameObject.AddComponent<Bouncer>().speed = 21f;
    }

    // a vent with a column of air blowing up out of it, steam rising
    static void Vent(Vector3 at, float height, float radius = 2f)
    {
        var k = AK("metal");
        // a low grate (low enough to ride straight onto)
        k.Box(at + Vector3.up * 0.06f, new Vector3(radius * 1.6f, 0.12f, radius * 1.6f), Quaternion.identity, 1f, 1f);
        for (float x = -radius * 0.6f; x <= radius * 0.6f; x += 0.4f)
            AK("white", "e").Box(at + new Vector3(x, 0.13f, 0f), new Vector3(0.08f, 0.02f, radius * 1.4f), Quaternion.identity, 1f, 1f, new Color32(60, 240, 255, 255));
        AkBox(at + Vector3.up * 0.06f, new Vector3(radius * 1.6f, 0.12f, radius * 1.6f));
        var go = new GameObject("Updraft", typeof(Updraft), typeof(ParticleSystem));
        go.transform.SetParent(akRoot, false);
        go.transform.position = at;
        var u = go.GetComponent<Updraft>();
        u.radius = radius; u.height = height; u.lift = Mathf.Clamp(height * 0.7f, 14f, 30f);
        var ps = go.GetComponent<ParticleSystem>();
        ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
        var main = ps.main;
        main.loop = true; main.playOnAwake = true; main.prewarm = true;
        main.startLifetime = Mathf.Min(4f, height / 10f);
        main.startSpeed = new ParticleSystem.MinMaxCurve(8f, 12f);
        main.startSize = new ParticleSystem.MinMaxCurve(0.4f, 1.2f);
        main.startColor = new ParticleSystem.MinMaxGradient(new Color(0.75f, 0.95f, 1f, 0.35f), new Color(1f, 1f, 1f, 0.2f));
        main.simulationSpace = ParticleSystemSimulationSpace.World;
        main.maxParticles = 300;
        var em = ps.emission; em.rateOverTime = 40f;
        var shape = ps.shape; shape.shapeType = ParticleSystemShapeType.Circle; shape.radius = radius * 0.8f;
        shape.rotation = new Vector3(-90f, 0f, 0f);
        var fade = ps.colorOverLifetime; fade.enabled = true;
        var grad = new Gradient();
        grad.SetKeys(new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(Color.white, 1f) },
                     new[] { new GradientAlphaKey(0.6f, 0f), new GradientAlphaKey(0f, 1f) });
        fade.color = grad;
        go.GetComponent<ParticleSystemRenderer>().sharedMaterial = Mat("Sparks", "Sprites/Default");
    }

    // a one-shot burst of particles (an explosion's fireball or smoke), played from code
    static ParticleSystem Burst(Transform parent, string name, Color a, Color b, float size0, float size1, float speed0, float speed1, float life, int count)
    {
        var go = new GameObject(name, typeof(ParticleSystem));
        go.transform.SetParent(parent, false);
        go.transform.localPosition = Vector3.up;
        var ps = go.GetComponent<ParticleSystem>();
        ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
        var main = ps.main;
        main.loop = false; main.playOnAwake = false; main.duration = 0.5f;
        main.startLifetime = new ParticleSystem.MinMaxCurve(life * 0.6f, life);
        main.startSpeed = new ParticleSystem.MinMaxCurve(speed0, speed1);
        main.startSize = new ParticleSystem.MinMaxCurve(size0, size1);
        main.startColor = new ParticleSystem.MinMaxGradient(a, b);
        main.simulationSpace = ParticleSystemSimulationSpace.World;
        main.gravityModifier = -0.2f;
        main.maxParticles = count * 2;
        var em = ps.emission; em.rateOverTime = 0f;
        em.SetBursts(new[] { new ParticleSystem.Burst(0f, (short)count) });
        var shape = ps.shape; shape.shapeType = ParticleSystemShapeType.Sphere; shape.radius = 1f;
        var fade = ps.colorOverLifetime; fade.enabled = true;
        var grad = new Gradient();
        grad.SetKeys(new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(new Color(0.5f, 0.4f, 0.4f), 1f) },
                     new[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(0f, 1f) });
        fade.color = grad;
        var grow = ps.sizeOverLifetime; grow.enabled = true; grow.size = new ParticleSystem.MinMaxCurve(1f, AnimationCurve.Linear(0f, 0.6f, 1f, 1.6f));
        go.GetComponent<ParticleSystemRenderer>().sharedMaterial = Mat("Sparks", "Sprites/Default");
        return ps;
    }

    // ---- the level --------------------------------------------------------------------------------------

    // -executeMethod SkateWorldBuilder.AkibaFromCommandLine: just this level, its test runs and screenshots
    public static void AkibaFromCommandLine()
    {
        try { BuildAkiba(); SlideTests.RunAkiba(); AkibaShots(); }
        catch (System.Exception e) { Debug.LogException(e); EditorApplication.Exit(1); return; }
        EditorApplication.Exit(0);
    }

    public static void BuildAkiba()
    {
        Directory.CreateDirectory(Folder);
        featureCount = 0;
        featureFile = null;
        featureAsset = Folder + "/AkibaFeatures.asset";
        if (AssetDatabase.LoadMainAssetAtPath(featureAsset) != null) AssetDatabase.DeleteAsset(featureAsset);
        keepClear.Clear(); akKits.Clear(); akMats.Clear(); akLots.Clear(); akKeepOut.Clear();
        akNodes.Clear(); akLinks.Clear(); akUsed.Clear(); akLand.Clear(); akRunUps.Clear(); akRails = null;
        ark = new System.Random(19990629);
        floorAt = AkFloor;
        ImportAkibaTextures();

        // ramps, rails, ledges: plain shapes in the PSX shader (white texture, vertex colours), thin ink lines
        RampTop = new Color32(255, 200, 80, 255); RampSide = new Color32(170, 160, 190, 255); RampSide2 = new Color32(120, 220, 255, 255);
        Metal = new Color32(200, 200, 215, 255); RailCol = new Color32(255, 214, 40, 255);
        Concrete = new Color32(170, 168, 180, 255); ConcreteDark = new Color32(130, 126, 140, 255);
        toonMat = AkMat("white", "");
        outlineMat = Mat("AkibaOutline", "3daigamesolo/World/Outline");
        outlineMat.SetColor("_OutlineColor", new Color(0.05f, 0.02f, 0.09f));
        outlineMat.SetFloat("_OutlineWidth", 1f);
        outlineMat.SetColor("_Haze", new Color(0.16f, 0.08f, 0.24f)); outlineMat.SetColor("_HazeHigh", new Color(0.12f, 0.06f, 0.2f));
        outlineMat.SetFloat("_FogDensity", 0.003f); outlineMat.SetFloat("_FogHeight", 900f); outlineMat.SetFloat("_FogMax", 0.95f);
        farOutlineMat = outlineMat;
        var sky = Mat("AkibaSky", "3daigamesolo/World/Sky");
        sky.SetColor("_Zenith", new Color(0.05f, 0.03f, 0.14f)); sky.SetColor("_Horizon", new Color(0.55f, 0.24f, 0.5f));
        sky.SetColor("_Below", new Color(0.16f, 0.08f, 0.24f)); sky.SetColor("_Cloud", new Color(0.42f, 0.22f, 0.5f));
        sky.SetColor("_CloudShade", new Color(0.24f, 0.11f, 0.32f)); sky.SetFloat("_CloudCover", 0.45f);

        var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
        RenderSettings.skybox = null;
        RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Flat;
        RenderSettings.ambientLight = Color.white;
        RenderSettings.fog = false;

        featureRoot = new GameObject("Skate features").transform;
        akRoot = new GameObject("Akiba").transform;
        akCol = new GameObject("Colliders").transform;
        akCol.SetParent(akRoot, false);

        AkAddNode("Street", NGround, 0f, Rect.MinMaxRect(-AkBack - 8f, -AkL - 30f, AkBack + 8f, AkL + 30f));
        AkPlanKeepOuts();
        AkGround();
        AkBuildings();
        AkWalkways();
        AkViaduct();
        AkIslands();
        AkLifts();
        AkEscalators();
        AkStops();
        AkStreetStuff();
        AkFlyingBuses();
        AkFlyingCars();
        AkAutoLinks();
        AkTraffic();
        AkBackdrop();
        AkReportGraph();
        FlushAkiba(akRoot);

        var skyGo = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        skyGo.name = "Sky";
        Object.DestroyImmediate(skyGo.GetComponent<Collider>());
        skyGo.transform.localScale = Vector3.one * 4000f;
        skyGo.GetComponent<Renderer>().sharedMaterial = sky;

        var start = new GameObject("Start");
        start.transform.SetPositionAndRotation(new Vector3(16f, Kerb + 0.2f, -110f), Quaternion.LookRotation(Vector3.forward));
        var camGO = new GameObject("Main Camera", typeof(Camera), typeof(AudioListener), typeof(SlideHUD), typeof(SkateAutoShot), typeof(LevelSwitcher), typeof(PSXCamera));
        camGO.tag = "MainCamera";
        var cam = camGO.GetComponent<Camera>();
        cam.nearClipPlane = 0.1f; cam.farClipPlane = 3000f;
        cam.clearFlags = CameraClearFlags.SolidColor;
        cam.backgroundColor = new Color(0.16f, 0.08f, 0.24f);
        var psx = camGO.GetComponent<PSXCamera>();
        psx.fogColor = new Color(0.16f, 0.08f, 0.24f); psx.fogStart = 90f; psx.fogEnd = 520f;
        psx.height = 540; psx.snapGrid = new Vector2(640f, 360f); psx.affine = 0.15f;
        psx.ambient = new Color(0.55f, 0.5f, 0.66f); psx.moonStrength = 0.45f;
        psx.Apply();
        var player = BuildPlayer(start.transform, camGO.transform);
        player.fallLimit = -30f;
        camGO.GetComponent<SlideHUD>().player = player;
        camGO.GetComponent<SlideHUD>().levelName = "Akiba";
        camGO.transform.SetPositionAndRotation(new Vector3(16f, 2.5f, -115f), Quaternion.LookRotation(Vector3.forward));
        player.board = BuildBoard(new Vector3(16f, Kerb, -108f), Quaternion.LookRotation(Vector3.forward));
        TowerCheckpoint(akRoot, new Vector3(18f, Kerb, -110f), "Akiba");

        EditorSceneManager.SaveScene(scene, AkibaPath);
        SetBuildScenes();
        AssetDatabase.SaveAssets();
        Physics.SyncTransforms();
        Debug.Log("SKATE_AKIBA_BUILT features=" + featureCount + " materials=" + akMats.Count + " photos=" + (Directory.Exists(AkibaPhotos) ? Directory.GetFiles(AkibaPhotos, "*.png").Length : 0));
    }

    // the walkways, escalators, lifts and stops along the fronts: the buildings' signs and the pavement
    // stalls keep out of their way
    static void AkPlanKeepOuts()
    {
        foreach (var s in new[] { -1f, 1f })
        {
            // (and nothing sticking out above them either, so vents can blow you up the fronts to the roofs)
            foreach (var (z0, z1) in AkWalkSpans)
                akKeepOut.Add(Box3(s * (AkFront - 3f), 40f, (z0 + z1) / 2f, 8.5f, 69f, z1 - z0 + 1f));
            akKeepOut.Add(Box3(s * (AkPlazaFront - 3f), 40f, 0f, 8.5f, 64f, 62f));
        }
        foreach (var e in AkEscalatorDefs)
        {
            Vector3 a = e.Item1, b = e.Item2;
            akKeepOut.Add(new Bounds((a + b) / 2f, new Vector3(Mathf.Abs(a.x - b.x) + 4f, Mathf.Abs(a.y - b.y) + 6f, Mathf.Abs(a.z - b.z) + 4f)));
        }
        foreach (var (x, z, _) in AkLiftDefs) akKeepOut.Add(Box3(x, 50f, z, 5f, 100f, 5f));
        foreach (var r in AkStopRects) akKeepOut.Add(Box3(r.center.x, 4f, r.center.y, r.width + 2f, 8f, r.height + 22f));
    }

    static Bounds Box3(float x, float y, float z, float sx, float sy, float sz) { return new Bounds(new Vector3(x, y, z), new Vector3(sx, sy, sz)); }

    // ---- the ground ----------------------------------------------------------------------------------------

    static void AkGround()
    {
        AkBox(new Vector3(0f, -0.5f, 0f), new Vector3(700f, 1f, 700f));
        AK("asphalt").Ground(-AkRoad, -AkL, AkRoad, AkL, 0f, 8f, 8f);
        foreach (var s in new[] { -1f, 1f })
        {
            foreach (var (z0, z1, fr, tex) in new[] { (-AkL, -AkPlazaHalf, AkFront, "pavement"), (-AkPlazaHalf, AkPlazaHalf, AkPlazaFront, "plaza"), (AkPlazaHalf, AkL, AkFront, "pavement") })
            {
                float xa = s > 0 ? AkRoad : -fr, xb = s > 0 ? fr : -AkRoad;
                AK(tex).Ground(xa, z0, xb, z1, Kerb, tex == "plaza" ? 5f : 4f, 8f);
                AkBox(new Vector3((xa + xb) / 2f, Kerb / 2f, (z0 + z1) / 2f), new Vector3(xb - xa, Kerb, z1 - z0));
            }
            AK("concrete").Box(new Vector3(s * (AkRoad + 0.1f), Kerb / 2f, 0f), new Vector3(0.2f, Kerb, AkL * 2f), Quaternion.identity, 4f, 4f);
            AK("tactile").Ground(s * (AkRoad + 1.2f) - 0.3f, -AkL, s * (AkRoad + 1.2f) + 0.3f, AkL, Kerb + 0.02f, 0.6f, 20f);
            // the alley round the back
            float bx0 = s > 0 ? AkBack : -AkBack - 8f, bx1 = s > 0 ? AkBack + 8f : -AkBack;
            AK("asphalt").Ground(bx0, -AkL - 36f, bx1, AkL + 36f, 0f, 8f, 8f);
            // and the ends, behind the end buildings
            AK("asphalt").Ground(-AkBack - 8f, s > 0 ? AkL + 30f : -AkL - 36f, AkBack + 8f, s > 0 ? AkL + 36f : -AkL - 30f, 0f, 8f, 8f);
        }
        // lane markings, the centre line and the crossings into the plaza
        var w = AK("white", "e");
        for (float z = -AkL + 4f; z < AkL - 4f; z += 8f)
            foreach (var x in new[] { -4f, 4f })
                w.Box(new Vector3(x, 0.02f, z), new Vector3(0.16f, 0.02f, 4f), Quaternion.identity, 1f, 1f);
        foreach (var x in new[] { -0.15f, 0.15f })
            AK("white", "").Box(new Vector3(x, 0.02f, 0f), new Vector3(0.12f, 0.02f, AkL * 2f - 8f), Quaternion.identity, 1f, 1f, new Color32(255, 200, 40, 255));
        foreach (var cz in new[] { -AkPlazaHalf + 3f, 0f, AkPlazaHalf - 3f })
            for (float x = -AkRoad + 0.8f; x < AkRoad; x += 1.6f)
                w.Box(new Vector3(x, 0.025f, cz), new Vector3(0.9f, 0.02f, 4f), Quaternion.identity, 1f, 1f);
        // quarter pipes across both ends
        foreach (var s in new[] { -1f, 1f })
            QuarterPipe("End wall", Matrix4x4.TRS(new Vector3(0f, 0f, s * (AkL - 4.6f)), Quaternion.LookRotation(new Vector3(0f, 0f, s)), Vector3.one), AkFront * 2f, 3.6f, 1f);
        // street lamps along the kerbs (not across the plaza)
        for (float z = -AkL + 14f; z < AkL - 10f; z += 22f)
            foreach (var s in new[] { -1f, 1f })
            {
                if (Mathf.Abs(z) < AkPlazaHalf + 2f || Mathf.Abs(z - AkViaductZ) < 7f) continue;
                Vector3 p = new Vector3(s * (AkRoad + 0.6f), Kerb, z);
                AK("metal").Cylinder(p, p + Vector3.up * 6.5f, 0.12f, 6, 2f, new Color32(150, 150, 170, 255));
                AK("metal").Cylinder(p + Vector3.up * 6.5f, p + Vector3.up * 6.5f + new Vector3(-s * 1.6f, 0.3f, 0f), 0.08f, 6, 2f, new Color32(150, 150, 170, 255));
                AK("white", "e").Box(p + new Vector3(-s * 1.8f, 6.7f, 0f), new Vector3(0.7f, 0.2f, 0.4f), Quaternion.identity, 1f, 1f, new Color32(255, 240, 200, 255));
                var cap = new GameObject("Lamp post").AddComponent<CapsuleCollider>();
                cap.transform.SetParent(akCol, false); cap.transform.position = p + Vector3.up * 3.25f; cap.radius = 0.14f; cap.height = 6.5f;
            }
        // walls round the outside, past the alleys
        foreach (var s in new[] { -1f, 1f })
        {
            AkBox(new Vector3(s * (AkBack + 8.5f), 60f, 0f), new Vector3(1f, 120f, AkL * 2f + 80f));
            AkBox(new Vector3(0f, 60f, s * (AkL + 36.5f)), new Vector3(AkBack * 2f + 20f, 120f, 1f));
        }
    }

    // ---- the buildings -------------------------------------------------------------------------------------

    // along each side, south to north: (z from, z to, height, kind). Kinds: 0 a building; 1 a landmark tower
    // (a glass lift up its front, a giant screen); 2 a gap, an alley through to the back; 3 the railway runs
    // through it
    static readonly float[,] AkEastLots = {
        { -120, -106, 24, 0 }, { -106, -92, 36, 0 }, { -92, -78, 18, 0 }, { -78, -64, 30, 0 }, { -64, -58, 0, 2 }, { -58, -36, 72, 1 },
        { -36, -14, 30, 0 }, { -14, 10, 20, 0 }, { 10, 36, 44, 0 },
        { 36, 58, 80, 1 }, { 58, 72, 26, 0 }, { 72, 88, 40, 0 }, { 88, 94, 0, 2 }, { 94, 106, 22, 3 }, { 106, 120, 30, 0 } };
    static readonly float[,] AkWestLots = {
        { -120, -104, 32, 0 }, { -104, -88, 20, 0 }, { -88, -72, 44, 0 }, { -72, -66, 0, 2 }, { -66, -56, 16, 0 }, { -56, -36, 64, 1 },
        { -36, -12, 24, 0 }, { -12, 14, 38, 0 }, { 14, 36, 18, 0 },
        { 36, 56, 76, 1 }, { 56, 70, 22, 0 }, { 70, 86, 34, 0 }, { 86, 94, 0, 2 }, { 94, 106, 24, 3 }, { 106, 120, 42, 0 } };

    static void AkBuildings()
    {
        foreach (var side in new[] { -1f, 1f })
        {
            var lots = side > 0 ? AkEastLots : AkWestLots;
            for (int i = 0; i < lots.GetLength(0); i++)
            {
                float z0 = lots[i, 0], z1 = lots[i, 1], h = lots[i, 2];
                int kind = (int)lots[i, 3];
                float front = AkFrontAt((z0 + z1) / 2f);
                Rect lot = side > 0 ? Rect.MinMaxRect(front, z0, AkBack, z1) : Rect.MinMaxRect(-AkBack, z0, -front, z1);
                if (kind == 2) AkAlley(lot);
                else AkLot(lot, h, side, kind);
            }
        }
        foreach (var s in new[] { -1f, 1f }) AkEndBuilding(s);
    }

    // a building: a shopfront at street level, a photo facade above, signs sticking out over the street, sign
    // bands, an LED ticker, a billboard and clutter at the back of the roof; stalls and machines on the
    // pavement in front
    static void AkLot(Rect lot, float h, float side, int kind)
    {
        float face = -side;
        Vector3 n = new Vector3(face, 0f, 0f);
        float fx = side > 0 ? lot.xMin : lot.xMax, bx = side > 0 ? lot.xMax : lot.xMin, w = lot.height, zc = lot.center.y;
        bool tall = h > 50f;
        AkBox(new Vector3(lot.center.x, h / 2f, zc), new Vector3(lot.width, h, w));
        string fac = tall ? "fac_tower_" + AI(0, 4) : "facade_" + AI(0, 6);
        float tu = tall ? 16f : 12f, tv = tall ? 21f : 16f;
        Vector3 fc = new Vector3(fx, 0f, zc);
        FrontWall(AK("shop_" + AI(0, 8), "e"), fc, n, w, 0f, 3.6f, 4.8f, 3.6f);
        FrontWall(AK(fac), fc, n, w, 3.6f, h, tu, tv, 3.6f);
        var sk = AK(tall ? fac : "fac_side");
        FrontWall(sk, new Vector3(lot.center.x, 0f, lot.yMin), Vector3.back, lot.width, 0f, h, tu, tv);
        FrontWall(sk, new Vector3(lot.center.x, 0f, lot.yMax), Vector3.forward, lot.width, 0f, h, tu, tv);
        FrontWall(sk, new Vector3(bx, 0f, zc), -n, w, 0f, h, tu, tv);
        AK("roof").Ground(lot.xMin, lot.yMin, lot.xMax, lot.yMax, h, 8f, 8f);
        // a low wall along the back of the roof (the street side and the ends are open: ride from roof to roof)
        Vector3 pc = new Vector3(bx - side * 0.15f, h + 0.3f, zc);
        AK("concrete").Box(pc, new Vector3(0.3f, 0.6f, w), Quaternion.identity, 3f, 3f);
        AkBox(pc, new Vector3(0.3f, 0.6f, w));
        akLots.Add((lot, h, side));
        string name = (kind == 1 ? "Tower " : "Roof ") + (side > 0 ? "E" : "W") + Mathf.RoundToInt(zc) + " (" + h + "m)";
        int node = AkAddNode(name, NRoof, h, lot);
        // things go on the street half of the roof; the clutter's at the back
        float depth = Mathf.Min(lot.width * 0.6f, 18f);
        akNodes[node].pads.Clear();
        akNodes[node].pads.Add(side > 0 ? Rect.MinMaxRect(fx, lot.yMin, fx + depth, lot.yMax) : Rect.MinMaxRect(fx - depth, lot.yMin, fx, lot.yMax));

        // an LED ticker over the shopfront, sign bands, signs sticking out (solid: you can't ride through them)
        if (!Kept(Box3(fx, 3.85f, zc, 1f, 0.6f, w)))
            AK("led_" + AI(0, 3), "s").Panel(new Vector3(fx + face * 0.12f, 3.85f, zc), Rt(n) * (w / 2f - 0.3f), Vector3.up * 0.22f, null, false, new Rect(0f, 0f, w / 6.4f, 1f));
        int bands = AI(1, tall ? 3 : 4);
        for (int b = 0; b < bands; b++)
        {
            float y = AR(5f, Mathf.Min(Mathf.Max(6f, h - 3f), 30f)), bw = Mathf.Min(w - 1f, AR(5f, 9f));
            float bz = zc + AR(-(w - bw) / 2f, (w - bw) / 2f);
            string tex = "sign_h_" + AI(0, 6), st = ark.NextDouble() < 0.3 ? "f" : "e";
            if (Kept(Box3(fx, y, bz, 1f, bw / 2.7f + 0.4f, bw))) continue;
            AK(tex, st).Panel(new Vector3(fx + face * 0.06f, y, bz), Rt(n) * (bw / 2f), Vector3.up * (bw / 5.4f));
        }
        int vs = Mathf.Clamp(Mathf.RoundToInt(w / 7f), 1, 3);
        for (int i = 0; i < vs; i++)
        {
            float z = Mathf.Lerp(lot.yMin + 1.5f, lot.yMax - 1.5f, (i + 0.5f) / vs);
            float sh = Mathf.Min(AR(3.5f, 6f), h - 6f);
            if (sh < 2.5f) continue;
            float y = AR(5f, Mathf.Max(5.1f, Mathf.Min(h, 28f) - sh - 1f)) + sh / 2f;
            string st = ark.NextDouble() < 0.35 ? "f" : "e", tex = "sign_v_" + AI(0, 8);
            Vector3 sc = new Vector3(fx + face * 0.85f, y, z);
            if (Kept(Box3(sc.x, y, z, 2.2f, sh + 1f, 2f))) continue;
            // a sign on each side of a thin frame
            AK(tex, st).Panel(sc + Vector3.forward * 0.09f, Rt(Vector3.forward) * 0.65f, Vector3.up * sh / 2f);
            AK(tex, st).Panel(sc + Vector3.back * 0.09f, Rt(Vector3.back) * 0.65f, Vector3.up * sh / 2f);
            AK("metal").Box(sc, new Vector3(1.34f, sh + 0.12f, 0.1f), Quaternion.identity, 1f, 1f);
            AkBox(sc, new Vector3(1.4f, sh + 0.12f, 0.2f));
        }
        if (ark.NextDouble() < 0.4)
            AK("graffiti_" + AI(0, 6), "").Panel(new Vector3(lot.center.x, AR(4.5f, 7f), lot.yMin - 0.06f), Rt(Vector3.back) * 2.8f, Vector3.up * 1.4f);

        // up top, at the back: a billboard facing the street, air conditioners, a water tank
        if (ark.NextDouble() < 0.7 && lot.width > 12f)
        {
            float bh = AR(6f, tall ? 12f : 9f), bw2 = Mathf.Min(w - 2f, bh * 1.6f);
            Vector3 bc = new Vector3(bx - side * 2.5f, h + 1.6f + bh / 2f, zc);
            AK("billboard_" + AI(0, 10), ark.NextDouble() < 0.2 ? "f" : "e").Panel(bc + n * 0.14f, Rt(n) * bw2 / 2f, Vector3.up * bh / 2f);
            AK("metal").Box(bc, new Vector3(0.2f, bh, bw2), Quaternion.identity, 2f, 2f);
            foreach (var o in new[] { -bw2 / 2.5f, bw2 / 2.5f })
            {
                AK("metal").Box(new Vector3(bc.x, h + 0.8f, bc.z + o), new Vector3(0.3f, 1.6f, 0.3f), Quaternion.identity, 1f, 1f);
                AkBox(new Vector3(bc.x, h + 0.8f, bc.z + o), new Vector3(0.3f, 1.6f, 0.3f));
            }
            AkBox(bc, new Vector3(0.3f, bh, bw2));
        }
        for (int i = 0; i < AI(1, 4); i++)
        {
            Vector3 ac = new Vector3(bx - side * AR(4.5f, Mathf.Max(5f, lot.width * 0.35f)), h + 0.5f, zc + AR(-w / 2f + 1.5f, w / 2f - 1.5f));
            AK("metal").Box(ac, new Vector3(1.4f, 1f, 1f), Quaternion.identity, 1f, 1f, new Color32(210, 210, 220, 255));
            AkBox(ac, new Vector3(1.4f, 1f, 1f));
        }
        if (ark.NextDouble() < 0.4 && lot.width > 16f)
        {
            Vector3 tc = new Vector3(bx - side * 6f, h, zc + AR(-w / 4f, w / 4f));
            AK("metal").Cylinder(tc + Vector3.up * 1.5f, tc + Vector3.up * 4f, 1.4f, 10, 2f, new Color32(190, 190, 200, 255));
            foreach (var o in new[] { new Vector3(-1f, 0f, -1f), new Vector3(1f, 0f, -1f), new Vector3(-1f, 0f, 1f), new Vector3(1f, 0f, 1f) })
                AK("metal").Box(tc + o + Vector3.up * 0.75f, new Vector3(0.15f, 1.5f, 0.15f), Quaternion.identity, 1f, 1f);
            AkBox(tc + Vector3.up * 2f, new Vector3(2.8f, 4f, 2.8f));
        }

        AkStalls(fx, lot, face);
        if (kind == 1) AkLandmark(lot, h, side, fx);
        if (kind == 3)
        {
            // the railway comes out of a tunnel in its front
            Vector3 portal = new Vector3(fx + face * 0.05f, AkViaductY + 2.6f, AkViaductZ);
            AK("white").Panel(portal, Rt(n) * 4.6f, Vector3.up * 2.9f, new Color32(12, 8, 18, 255));
            AK("concrete").Box(portal + n * 0.25f + Vector3.up * 3.1f, new Vector3(0.5f, 0.6f, 10.4f), Quaternion.identity, 2f, 2f);
            foreach (var o in new[] { -5f, 5f })
                AK("concrete").Box(new Vector3(portal.x + face * 0.25f, AkViaductY + 2.6f, AkViaductZ + o), new Vector3(0.5f, 5.8f, 0.5f), Quaternion.identity, 2f, 2f);
        }
    }

    // the four towers round the plaza: a giant screen on the front, a mast with a light on top, a checkpoint
    static void AkLandmark(Rect lot, float h, float side, float fx)
    {
        float face = -side, w = lot.height;
        Vector3 n = new Vector3(face, 0f, 0f);
        float sw = w - 4f, sh = sw * 0.56f, y = Mathf.Min(h - sh / 2f - 6f, 30f);
        Vector3 sc = new Vector3(fx + face * 0.6f, y, lot.center.y);
        AK("screen", "e").Panel(sc + n * 0.21f, Rt(n) * sw / 2f, Vector3.up * sh / 2f, null, false, new Rect(0.08f, 0.24f, 0.705f, 0.76f));
        AK("metal").Box(sc, new Vector3(0.4f, sh + 0.6f, sw + 0.6f), Quaternion.identity, 2f, 2f, new Color32(40, 40, 50, 255));
        AkBox(sc, new Vector3(0.4f, sh + 0.6f, sw + 0.6f));
        Vector3 mast = new Vector3(lot.center.x + side * 6f, h, lot.center.y);
        AK("metal").Cylinder(mast, mast + Vector3.up * 14f, 0.35f, 6, 3f, new Color32(220, 60, 60, 255));
        AK("white", "e").Ellipsoid(mast + Vector3.up * 14.4f, Vector3.one * 0.6f, 8, 5, new Color32(255, 60, 60, 255));
        var cap = new GameObject("Mast").AddComponent<CapsuleCollider>();
        cap.transform.SetParent(akCol, false); cap.transform.position = mast + Vector3.up * 7f; cap.radius = 0.4f; cap.height = 14f;
        TowerCheckpoint(akRoot, new Vector3(fx + side * 6f, h, lot.center.y + w * 0.3f), "Tower top");
    }

    static void AkAlley(Rect lot)
    {
        AK("asphalt").Ground(lot.xMin, lot.yMin, lot.xMax, lot.yMax, 0.01f, 8f, 8f);
        float side = Mathf.Sign(lot.center.x);
        // a couple of bins and some graffiti
        for (int i = 0; i < 2; i++)
        {
            Vector3 b = new Vector3(lot.center.x + side * AR(-8f, 12f), 0.6f, lot.center.y + (i == 0 ? -1.8f : 1.8f));
            AK("metal").Box(b, new Vector3(1.2f, 1.2f, 1.2f), Quaternion.identity, 1f, 1f, new Color32(60, 110, 70, 255));
            AkBox(b, new Vector3(1.2f, 1.2f, 1.2f));
        }
    }

    // a building closing off an end of the avenue: its front faces back up the street, with a giant screen
    static void AkEndBuilding(float s)
    {
        float h = s > 0 ? 48f : 40f, fz = s * AkL, bz = s * (AkL + 30f);
        Rect lot = Rect.MinMaxRect(-AkBack, Mathf.Min(fz, bz), AkBack, Mathf.Max(fz, bz));
        Vector3 n = new Vector3(0f, 0f, -s);
        AkBox(new Vector3(0f, h / 2f, lot.center.y), new Vector3(lot.width, h, lot.height));
        Vector3 fc = new Vector3(0f, 0f, fz);
        FrontWall(AK("shop_" + AI(0, 8), "e"), fc, n, lot.width, 0f, 3.6f, 4.8f, 3.6f);
        FrontWall(AK("fac_tower_" + AI(0, 4)), fc, n, lot.width, 3.6f, h, 16f, 21f, 3.6f);
        FrontWall(AK("fac_side"), new Vector3(0f, 0f, bz), -n, lot.width, 0f, h, 12f, 16f);
        foreach (var sx in new[] { -1f, 1f }) FrontWall(AK("fac_side"), new Vector3(sx * AkBack, 0f, lot.center.y), new Vector3(sx, 0f, 0f), lot.height, 0f, h, 12f, 16f);
        AK("roof").Ground(lot.xMin, lot.yMin, lot.xMax, lot.yMax, h, 8f, 8f);
        Vector3 sc = new Vector3(0f, h * 0.55f, fz - s * 0.6f);
        AK("screen", "e").Panel(sc + n * 0.21f, Rt(n) * 16f, Vector3.up * 9f, null, false, new Rect(0.08f, 0.24f, 0.705f, 0.76f));
        AK("metal").Box(sc, new Vector3(32.6f, 18.6f, 0.4f), Quaternion.identity, 2f, 2f, new Color32(40, 40, 50, 255));
        AkBox(sc, new Vector3(32.6f, 18.6f, 0.4f));
        int node = AkAddNode(s > 0 ? "North end roof (" + h + "m)" : "South end roof (" + h + "m)", NRoof, h, lot);
        akNodes[node].pads.Clear();
        akNodes[node].pads.Add(Rect.MinMaxRect(-AkFront, Mathf.Min(fz, fz + s * 12f), AkFront, Mathf.Max(fz, fz + s * 12f)));
        akLots.Add((lot, h, 0f));
    }

    // stalls with a lit front and a flat roof to ride onto, rows of vending machines, capsule toy machines
    static void AkStalls(float fx, Rect lot, float face)
    {
        Vector3 n = new Vector3(face, 0f, 0f);
        float z = lot.yMin + 0.6f;
        while (z < lot.yMax - 3.2f)
        {
            float kind = (float)ark.NextDouble();
            float len = kind < 0.45f ? AR(3f, 4.5f) : kind < 0.75f ? AI(2, 5) * 1.05f : AI(2, 4) * 1.2f;
            if (Kept(Box3(fx + face * 1.6f, 1.5f, z + len / 2f, 3.6f, 3f, len + 0.4f))) { z += 2f; continue; }
            if (kind < 0.45f)
            {
                Vector3 c = new Vector3(fx + face * 1.4f, 1.3f + Kerb, z + len / 2f);
                AK("concrete").Box(c, new Vector3(2.8f, 2.6f, len), Quaternion.identity, 3f, 3f, null, false);
                AK("shop_" + AI(0, 8), "e").Panel(c + n * 1.42f, Rt(n) * len / 2f, Vector3.up * 1.2f);
                AK("roof").Box(c + Vector3.up * 1.4f + n * 0.4f, new Vector3(3.6f, 0.2f, len + 0.2f), Quaternion.identity, 3f, 3f);
                AkBox(c + Vector3.up * 0.1f, new Vector3(2.8f, 2.8f, len));
                var roofCol = AddBox(akCol, "Stall roof", c + Vector3.up * 1.4f + n * 0.4f, new Vector3(3.6f, 0.2f, len + 0.2f));
                if (ark.NextDouble() < 0.3)
                {
                    // a springy awning: stretched pink canvas that bounces you
                    roofCol.gameObject.AddComponent<Bouncer>().speed = 17f;
                    AK("white", "e").Box(c + Vector3.up * 1.53f + n * 0.4f, new Vector3(3.5f, 0.06f, len + 0.1f), Quaternion.identity, 1f, 1f, new Color32(255, 110, 190, 255));
                }
            }
            else if (kind < 0.75f)
            {
                int count = Mathf.RoundToInt(len / 1.05f);
                for (int i = 0; i < count; i++)
                {
                    Vector3 c = new Vector3(fx + face * 0.45f, 0.95f + Kerb, z + 0.5f + i * 1.05f);
                    AK("vending", "e").Panel(c + n * 0.41f, Rt(n) * 0.5f, Vector3.up * 0.95f);
                    AK("metal").Box(c, new Vector3(0.8f, 1.9f, 1f), Quaternion.identity, 1f, 1f, new Color32(220, 60, 70, 255));
                    AkBox(c, new Vector3(0.8f, 1.9f, 1f));
                }
            }
            else
            {
                Vector3 c = new Vector3(fx + face * 0.35f, 0.9f + Kerb, z + len / 2f);
                AK("gacha", "e").Panel(c + n * 0.31f, Rt(n) * len / 2f, Vector3.up * 0.9f);
                AK("white").Box(c, new Vector3(0.6f, 1.8f, len), Quaternion.identity, 1f, 1f);
                AkBox(c, new Vector3(0.6f, 1.8f, len));
            }
            z += len + AR(0.6f, 3f);
        }
    }

    // ---- walkways along the fronts, one floor up, with moving footbridges across --------------------------

    static readonly (float, float)[] AkWalkSpans = { (-106f, -58f), (56f, 92f) };
    static readonly float[] AkBridgeZ = { -80f, 68f };

    static void AkWalkways()
    {
        for (int i = 0; i < 2; i++)
        {
            var (z0, z1) = AkWalkSpans[i];
            var e = AkDeck(1f, AkFront - 6f, AkFront, z0, z1, AkWalkY);
            var w = AkDeck(-1f, AkFront - 6f, AkFront, z0, z1, AkWalkY);
            var b = AkFootbridge(AkBridgeZ[i], AkWalkY);
            int node = AkAddNode(i == 0 ? "South walkways" : "North walkways", NWalk, AkWalkY, e, w, b);
            akNodes[node].pads.Clear(); akNodes[node].pads.Add(e); akNodes[node].pads.Add(w);
            if (i == 0) akSouthWalk = node; else akNorthWalk = node;
        }
        var be = AkDeck(1f, AkPlazaFront - 6f, AkPlazaFront, -30f, 30f, AkBalconyY);
        var bw = AkDeck(-1f, AkPlazaFront - 6f, AkPlazaFront, -30f, 30f, AkBalconyY);
        akBalconyE = AkAddNode("Plaza balcony E", NWalk, AkBalconyY, be);
        akBalconyW = AkAddNode("Plaza balcony W", NWalk, AkBalconyY, bw);
        TowerCheckpoint(akRoot, new Vector3(AkPlazaFront - 1f, AkBalconyY, 12f), "Plaza balcony");
    }

    // a deck along a front from |x| = xIn to xOut, z0..z1, its top at y: a slab with a lit edge, a railing
    // to grind, posts down to the pavement, shop entrances along the wall
    static Rect AkDeck(float s, float xIn, float xOut, float z0, float z1, float y)
    {
        float len = z1 - z0, zc = (z0 + z1) / 2f, w = xOut - xIn;
        Vector3 c = new Vector3(s * (xIn + xOut) / 2f, y - 0.4f, zc);
        Vector3 size = new Vector3(w, 0.8f, len);
        AK("pavement").Box(c, size, Quaternion.identity, 4f, 4f, null, true, true);
        AkBox(c, size);
        Vector3 outward = new Vector3(-s, 0f, 0f);
        AK("led_" + AI(0, 3), "s").Panel(new Vector3(s * (xIn - 0.02f), y - 0.4f, zc), Rt(outward) * (len / 2f), Vector3.up * 0.3f, null, false, new Rect(0f, 0f, len / 6.4f, 1f));
        AK("white", "e").Box(new Vector3(s * (xIn + 0.1f), y + 0.02f, zc), new Vector3(0.1f, 0.04f, len), Quaternion.identity, 1f, 1f, new Color32(60, 240, 255, 255));
        for (float z = z0 + 0.4f; z < z1; z += 2.5f)
            AK("metal").Box(new Vector3(s * (xIn + 0.25f), y + 0.5f, z), new Vector3(0.07f, 1f, 0.07f), Quaternion.identity, 1f, 1f);
        Rail("Walkway railing", new[] { new Vector3(s * (xIn + 0.25f), y + 1.02f, z0 + 0.4f), new Vector3(s * (xIn + 0.25f), y + 1.02f, z1 - 0.4f) }, false);
        int posts = Mathf.Max(1, Mathf.RoundToInt(len / 12f));
        for (int i = 0; i <= posts; i++)
        {
            float z = Mathf.Lerp(z0 + 1f, z1 - 1f, i / (float)posts);
            Vector3 pc = new Vector3(s * (xIn + 0.35f), (y - 0.8f + Kerb) / 2f, z);
            AK("metal").Box(pc, new Vector3(0.45f, y - 0.8f - Kerb, 0.45f), Quaternion.identity, 1f, 2f, new Color32(150, 150, 170, 255));
            AkBox(pc, new Vector3(0.45f, y - 0.8f - Kerb, 0.45f));
        }
        // shop doors and signs along the wall at walkway level
        for (float z = z0 + 3f; z < z1 - 3f; z += AR(7f, 12f))
            AK("shop_" + AI(0, 8), "e").Panel(new Vector3(s * (xOut - 0.06f), y + 1.6f, z), Rt(outward) * 2.4f, Vector3.up * 1.6f);
        return s > 0 ? Rect.MinMaxRect(xIn, z0, xOut, z1) : Rect.MinMaxRect(-xOut, z0, -xIn, z1);
    }

    // a footbridge across the avenue between the walkways: two moving walkways, one each way, railings to grind
    static Rect AkFootbridge(float z, float y)
    {
        float x0 = -(AkFront - 6f), x1 = AkFront - 6f;
        Color32 green = new Color32(150, 210, 180, 255);
        AK("white").Box(new Vector3(0f, y - 0.6f, z), new Vector3(x1 - x0, 0.6f, 4.4f), Quaternion.identity, 1f, 1f, green, false, true);
        foreach (var lane in new[] { -1f, 1f })
        {
            // the moving belt: the steps texture scrolling the way it carries you
            Vector3 lc = new Vector3(0f, y - 0.15f, z + lane * 1.05f);
            Vector3 dir = new Vector3(lane, 0f, 0f);
            var col = AddBox(akCol, "Moving walkway", lc, new Vector3(x1 - x0, 0.3f, 2.1f));
            var esc = col.gameObject.AddComponent<Escalator>(); esc.direction = dir; esc.speed = 4f;
            var k = AK("escalator", lane > 0 ? "x" : "y");
            k.Quad(new Vector3(x0, y, z + lane * 1.05f - 1f), new Vector3(x0, y, z + lane * 1.05f + 1f), new Vector3(x1, y, z + lane * 1.05f + 1f), new Vector3(x1, y, z + lane * 1.05f - 1f),
                   new Vector2(0f, 0f), new Vector2(2f / 1.2f, 0f), new Vector2(2f / 1.2f, (x1 - x0) / 1.2f), new Vector2(0f, (x1 - x0) / 1.2f), Vector3.up);
        }
        foreach (var s in new[] { -1f, 1f })
        {
            AK("white").Box(new Vector3(0f, y + 0.55f, z + s * 2.15f), new Vector3(x1 - x0, 1.1f, 0.1f), Quaternion.identity, 1f, 1f, green);
            AkBox(new Vector3(0f, y + 0.55f, z + s * 2.15f), new Vector3(x1 - x0, 1.1f, 0.12f));
            Rail("Footbridge railing", new[] { new Vector3(x0 + 0.5f, y + 1.15f, z + s * 2.15f), new Vector3(x1 - 0.5f, y + 1.15f, z + s * 2.15f) }, false);
            foreach (var ax in new[] { -12f, -4f, 4f, 12f })
                AK("sign_h_" + AI(0, 6), "e").Panel(new Vector3(ax, y - 1.2f, z + s * 2.24f), Rt(new Vector3(0f, 0f, s)) * 1.9f, Vector3.up * 0.7f);
            AK("white").Box(new Vector3(0f, y - 1.2f, z + s * 2.15f), new Vector3(x1 - x0, 1.5f, 0.12f), Quaternion.identity, 1f, 1f, green);
            Vector3 post = new Vector3(s * (AkRoad + 1f), (y - 0.9f + Kerb) / 2f, z);
            AK("white").Box(post, new Vector3(0.6f, y - 0.9f - Kerb, 0.6f), Quaternion.identity, 1f, 1f, green);
            AkBox(post, new Vector3(0.6f, y - 0.9f - Kerb, 0.6f));
        }
        return Rect.MinMaxRect(x0, z - 2.1f, x1, z + 2.1f);
    }

    // ---- the railway over the north end, and the train ----------------------------------------------------

    static void AkViaduct()
    {
        float y = AkViaductY, z = AkViaductZ, half = AkFront;
        var c = AK("concrete");
        c.Box(new Vector3(0f, y - 0.7f, z), new Vector3(half * 2f, 1.4f, 10f), Quaternion.identity, 6f, 6f, null, true, true);
        AkBox(new Vector3(0f, y - 0.7f, z), new Vector3(half * 2f, 1.4f, 10f));
        foreach (var s in new[] { -1f, 1f })
        {
            c.Box(new Vector3(0f, y + 0.5f, z + s * 4.85f), new Vector3(half * 2f, 1f, 0.3f), Quaternion.identity, 6f, 6f);
            AkBox(new Vector3(0f, y + 0.5f, z + s * 4.85f), new Vector3(half * 2f, 1f, 0.3f));
            Rail("Viaduct wall", new[] { new Vector3(-half + 0.5f, y + 1.02f, z + s * 4.85f), new Vector3(half - 0.5f, y + 1.02f, z + s * 4.85f) }, false);
            AK("posters", "e").Box(new Vector3(0f, y - 0.7f, z + s * 5.02f), new Vector3(half * 2f, 1.2f, 0.02f), Quaternion.identity, 4f, 1.2f);
            Vector3 pier = new Vector3(s * (AkRoad + 1.2f), (y - 1.4f) / 2f, z);
            c.Box(pier, new Vector3(1.4f, y - 1.4f, 6f), Quaternion.identity, 3f, 3f);
            AkBox(pier, new Vector3(1.4f, y - 1.4f, 6f));
        }
        for (float x = -half; x < half; x += 1.5f)
            AK("concrete").Box(new Vector3(x, y + 0.05f, z), new Vector3(0.3f, 0.1f, 2.4f), Quaternion.identity, 1f, 1f);
        foreach (var rz in new[] { -0.72f, 0.72f })
            AK("metal").Box(new Vector3(0f, y + 0.18f, z + rz), new Vector3(half * 2f, 0.12f, 0.1f), Quaternion.identity, 4f, 1f);
        akRailway = AkAddNode("Railway", NWalk, y, Rect.MinMaxRect(-half + 1f, z - 4.6f, half - 1f, z + 4.6f));
        akNodes[akRailway].pads.Clear();
        akNodes[akRailway].pads.Add(Rect.MinMaxRect(-half + 1f, z - 4.6f, half - 1f, z - 2f));
        akNodes[akRailway].pads.Add(Rect.MinMaxRect(-half + 1f, z + 2f, half - 1f, z + 4.6f));
        TowerCheckpoint(akRoot, new Vector3(-16f, y, z + 3.4f), "Railway");

        // the train: comes out of one tunnel, crosses, goes into the other, and back
        var go = new GameObject("Train", typeof(Rigidbody), typeof(Mover));
        go.transform.SetParent(akRoot, false);
        go.GetComponent<Rigidbody>().isKinematic = true;
        var tk = new PSXKit();
        float carLen = 16f, tw = 2.9f, th = 3.5f;
        for (int i = 0; i < 2; i++)
        {
            float cz = (i - 0.5f) * (carLen + 0.8f);
            foreach (var sx in new[] { -1f, 1f })
                tk.Panel(new Vector3(sx * tw / 2f, th / 2f + 0.4f, cz), Rt(new Vector3(sx, 0f, 0f)) * carLen / 2f, Vector3.up * th / 2f);
            tk.Box(new Vector3(0f, th / 2f + 0.4f, cz), new Vector3(tw - 0.02f, th, carLen), Quaternion.identity, 50f, 50f, new Color32(200, 204, 214, 255), true, false);
            var bc = go.AddComponent<BoxCollider>();
            bc.center = new Vector3(0f, th / 2f + 0.4f, cz); bc.size = new Vector3(tw, th, carLen);
        }
        var tm = tk.Build("Train");
        SaveFeatureMesh(tm);
        go.AddComponent<MeshFilter>().sharedMesh = tm;
        go.AddComponent<MeshRenderer>().sharedMaterial = AkMat("train_side", "");
        var m = go.GetComponent<Mover>();
        m.path = new[] { new Vector3(-42f, y, z), new Vector3(42f, y, z) };
        m.loop = false; m.speed = 11f; m.wait = 5f; m.easeIn = 20f; m.turn = false;
        go.transform.rotation = Quaternion.LookRotation(Vector3.right);
    }

    // ---- the floating pieces of the city -------------------------------------------------------------------

    // (x, top, z, width, depth, kind). Kinds: 0 a piece of road, 1 a piece of pavement, 2 a shrine garden,
    // 3 a rooftop, 4 a bit of the plaza
    static readonly float[,] AkIslandDefs = {
        { 0, 7, -100, 10, 10, 0 }, { -14, 12, -88, 9, 9, 1 }, { 12, 16, -62, 9, 9, 3 }, { -6, 22, -46, 9, 9, 2 },
        { 16, 9, -28, 10, 9, 0 }, { -20, 14, -18, 9, 9, 1 }, { 8, 27, -10, 12, 12, 4 }, { 26, 20, 6, 9, 9, 3 },
        { -24, 33, 10, 9, 9, 3 }, { 2, 44, 22, 9, 9, 2 }, { 0, 58, -2, 14, 14, 2 }, { 16, 36, 34, 9, 9, 1 },
        { -12, 24, 44, 9, 9, 1 }, { 10, 15, 64, 9, 9, 0 }, { -8, 30, 80, 9, 9, 3 }, { 6, 9, 112, 9, 9, 0 },
        { 16, 42, -84, 9, 9, 3 }, { -16, 50, 62, 9, 9, 2 },
        { -4, 18, -72, 9, 9, 1 }, { 4, 31, -30, 9, 9, 3 }, { -12, 40, 0, 9, 9, 1 }, { 13, 50, 12, 9, 9, 3 }, { -2, 21, 98, 9, 9, 1 }, { 20, 28, -48, 9, 9, 1 } };
    static readonly int[] akIsland = new int[24];
    static readonly string[] AkIslandNames = { "Road chunk", "Pavement chunk", "Shrine garden", "Rooftop chunk", "Plaza chunk" };

    static void AkIslands()
    {
        Physics.SyncTransforms();
        for (int i = 0; i < AkIslandDefs.GetLength(0); i++)
        {
            float x = AkIslandDefs[i, 0], top = AkIslandDefs[i, 1], z = AkIslandDefs[i, 2], w = AkIslandDefs[i, 3], d = AkIslandDefs[i, 4];
            int kind = (int)AkIslandDefs[i, 5];
            akIsland[i] = AkChunk(new Vector3(x, top, z), w, d, kind, i);
        }
        // the crown: the highest, a shrine with a giant lucky cat
        var crown = akNodes[akIsland[10]];
        TowerCheckpoint(akRoot, crown.Centre + new Vector3(-4.5f, 0f, -4.5f), "Akiba crown");
        LuckyCat(crown.Centre + new Vector3(3.5f, 0f, 3.5f), 0.55f);
    }

    // a chunk of the city torn loose: its top is a bit of street (or a garden or a rooftop), its sides and
    // underneath raw earth and rock tapering to a point, with broken pipes and cables hanging off
    static int AkChunk(Vector3 c, float w, float d, int kind, int index)
    {
        float thick = 1.2f;
        string topTex = kind == 0 ? "asphalt" : kind == 1 ? "pavement" : kind == 2 ? "grass" : kind == 3 ? "roof" : "plaza";
        AK(topTex).Ground(c.x - w / 2f, c.z - d / 2f, c.x + w / 2f, c.z + d / 2f, c.y, 4f, 4f);
        AK("earth").Box(c + Vector3.down * thick / 2f, new Vector3(w, thick, d), Quaternion.identity, 3f, 3f, null, false, false);
        AkBox(c + Vector3.down * thick / 2f, new Vector3(w, thick, d));
        // how far down the rock can hang before it gets in the way of what's underneath
        RaycastHit hit;
        float below = Physics.Raycast(c + Vector3.down * (thick + 0.2f), Vector3.down, out hit, 200f, ~0, QueryTriggerInteraction.Ignore) ? hit.point.y : 0f;
        float hang = Mathf.Clamp(c.y - thick - below - 4.5f, 0.8f, Mathf.Max(w, d) * 0.85f);
        // the underside: rings of jagged earth narrowing to a point
        var k = AK("earth");
        var rnd = new System.Random(index * 31 + 7);
        System.Func<float, float, float> J = (a, b) => a + (float)rnd.NextDouble() * (b - a);
        int seg = 10;
        var rings = new List<Vector3[]>();
        float[] fr = { 1f, 0.72f, 0.42f };
        float[] dy = { 0f, 0.4f, 0.75f };
        for (int r = 0; r < fr.Length; r++)
        {
            var ring = new Vector3[seg];
            for (int i = 0; i < seg; i++)
            {
                float a = i * Mathf.PI * 2f / seg;
                // round the rectangle's edge on the first ring, jagged further in
                Vector3 edge = new Vector3(Mathf.Clamp(Mathf.Cos(a) * 1.5f, -1f, 1f) * w / 2f, 0f, Mathf.Clamp(Mathf.Sin(a) * 1.5f, -1f, 1f) * d / 2f);
                ring[i] = c + Vector3.down * (thick + hang * dy[r] + (r > 0 ? J(-0.4f, 0.4f) : 0f)) + edge * fr[r] * (r > 0 ? J(0.85f, 1.1f) : 1f);
            }
            rings.Add(ring);
        }
        Vector3 tip = c + Vector3.down * (thick + hang) + new Vector3(J(-1f, 1f), 0f, J(-1f, 1f));
        for (int r = 0; r < rings.Count; r++)
            for (int i = 0; i < seg; i++)
            {
                Vector3 a0 = rings[r][i], a1 = rings[r][(i + 1) % seg];
                if (r + 1 < rings.Count)
                {
                    Vector3 b0 = rings[r + 1][i], b1 = rings[r + 1][(i + 1) % seg];
                    k.Quad(a0, a1, b1, b0, new Vector2(i / 3f, r), new Vector2((i + 1) / 3f, r), new Vector2((i + 1) / 3f, r + 1), new Vector2(i / 3f, r + 1), FlatDir((a0 + a1) / 2f - c) + Vector3.down * 0.6f);
                }
                else k.Quad(a0, a1, tip, tip, new Vector2(i / 3f, r), new Vector2((i + 1) / 3f, r), new Vector2((i + 0.5f) / 3f, r + 1), new Vector2((i + 0.5f) / 3f, r + 1), FlatDir((a0 + a1) / 2f - c) + Vector3.down * 0.6f);
            }
        AkBox(c + Vector3.down * (thick + hang * 0.4f), new Vector3(w * 0.6f, hang * 0.8f, d * 0.6f));
        // broken pipes and cables hanging off the bottom
        for (int i = 0; i < 2; i++)
        {
            Vector3 p0 = rings[1][rnd.Next(seg)];
            AK("metal").Cylinder(p0, p0 + new Vector3(J(-0.6f, 0.6f), -J(1.2f, 2.6f), J(-0.6f, 0.6f)), 0.1f, 6, 2f, new Color32(120, 110, 100, 255));
        }

        // what's on top
        var rk = new System.Random(index * 13 + 3);
        System.Func<float, float, float> R2 = (a, b) => a + (float)rk.NextDouble() * (b - a);
        if (kind == 0)
        {
            // a bit of road: a lane line and a kerb along one side
            AK("white", "e").Box(c + new Vector3(0f, 0.02f, 0f), new Vector3(0.16f, 0.02f, d - 1f), Quaternion.identity, 1f, 1f);
            Vector3 kc = c + new Vector3(w / 2f - 0.4f, 0.12f, 0f);
            AK("concrete").Box(kc, new Vector3(0.8f, 0.24f, d), Quaternion.identity, 2f, 2f);
            AkBox(kc, new Vector3(0.8f, 0.24f, d));
            if (w >= 9f) Hump("Chunk kicker", c + new Vector3(-w / 4f, 0f, -d / 2f + 1f), Vector3.forward, 2.5f, 24f, 2.4f, RampSide2);
        }
        else if (kind == 1)
        {
            // a bit of pavement: a row of vending machines along one edge (a ledge to grind)
            int count = Mathf.Max(1, Mathf.FloorToInt(d / 1.1f) - 2);
            for (int i = 0; i < count && w > 5f; i++)
            {
                Vector3 vc = c + new Vector3(-w / 2f + 0.5f, 0.95f, -d / 2f + 1.4f + i * 1.05f);
                AK("vending", "e").Panel(vc + Vector3.right * 0.41f, Rt(Vector3.right) * 0.5f, Vector3.up * 0.95f);
                AK("metal").Box(vc, new Vector3(0.8f, 1.9f, 1f), Quaternion.identity, 1f, 1f, new Color32(220, 60, 70, 255));
                AkBox(vc, new Vector3(0.8f, 1.9f, 1f));
            }
            AK("tactile").Ground(c.x + w / 2f - 1.2f, c.z - d / 2f, c.x + w / 2f - 0.6f, c.z + d / 2f, c.y + 0.02f, 0.6f, 20f);
        }
        else if (kind == 2)
        {
            // a shrine garden: a torii (its top beam's a rail), stone lanterns
            Color32 red = new Color32(230, 50, 40, 255), black = new Color32(30, 25, 30, 255);
            float tz = c.z - d / 2f + 1.6f;
            foreach (var ox in new[] { -1.8f, 1.8f })
            {
                AK("white").Cylinder(new Vector3(c.x + ox, c.y, tz), new Vector3(c.x + ox, c.y + 4.2f, tz), 0.22f, 8, 2f, red);
                var cap = new GameObject("Torii post").AddComponent<CapsuleCollider>();
                cap.transform.SetParent(akCol, false); cap.transform.position = new Vector3(c.x + ox, c.y + 2.1f, tz); cap.radius = 0.22f; cap.height = 4.2f;
            }
            AK("white").Box(new Vector3(c.x, c.y + 3.6f, tz), new Vector3(4.2f, 0.3f, 0.3f), Quaternion.identity, 1f, 1f, red);
            AK("white").Box(new Vector3(c.x, c.y + 4.35f, tz), new Vector3(5.4f, 0.3f, 0.45f), Quaternion.identity, 1f, 1f, black);
            AkBox(new Vector3(c.x, c.y + 4.35f, tz), new Vector3(5.4f, 0.3f, 0.45f));
            Rail("Torii", new[] { new Vector3(c.x - 2.6f, c.y + 4.52f, tz), new Vector3(c.x + 2.6f, c.y + 4.52f, tz) }, false);
            if (w >= 8f)
                foreach (var ox in new[] { -w / 2f + 1f, w / 2f - 1f })
                {
                    Vector3 l = new Vector3(c.x + ox, c.y, c.z + d / 2f - 1.2f);
                    AK("concrete").Box(l + Vector3.up * 0.6f, new Vector3(0.6f, 1.2f, 0.6f), Quaternion.identity, 1f, 1f);
                    AK("white", "e").Box(l + Vector3.up * 1.35f, new Vector3(0.5f, 0.3f, 0.5f), Quaternion.identity, 1f, 1f, new Color32(255, 220, 160, 255));
                    AkBox(l + Vector3.up * 0.75f, new Vector3(0.6f, 1.5f, 0.6f));
                }
        }
        else if (kind == 3)
        {
            // a rooftop: an air conditioner or two, a low wall along one edge with a rail on it
            Vector3 ac = c + new Vector3(w / 2f - 1.2f, 0.5f, d / 2f - 1.2f);
            AK("metal").Box(ac, new Vector3(1.4f, 1f, 1f), Quaternion.identity, 1f, 1f, new Color32(210, 210, 220, 255));
            AkBox(ac, new Vector3(1.4f, 1f, 1f));
            if (w > 5f)
            {
                Vector3 lc = c + new Vector3(0f, 0.3f, -d / 2f + 0.2f);
                AK("concrete").Box(lc, new Vector3(w - 2f, 0.6f, 0.3f), Quaternion.identity, 2f, 2f);
                AkBox(lc, new Vector3(w - 2f, 0.6f, 0.3f));
                Rail("Chunk ledge", new[] { lc + new Vector3(-w / 2f + 1.3f, 0.32f, 0f), lc + new Vector3(w / 2f - 1.3f, 0.32f, 0f) }, false);
            }
        }
        else
        {
            // a bit of the plaza: capsule toy machines, a bench to grind
            Vector3 g = c + new Vector3(-w / 2f + 0.5f, 0.9f, 0f);
            AK("gacha", "e").Panel(g + Vector3.right * 0.31f, Rt(Vector3.right) * 2.4f, Vector3.up * 0.9f);
            AK("white").Box(g, new Vector3(0.6f, 1.8f, 4.8f), Quaternion.identity, 1f, 1f);
            AkBox(g, new Vector3(0.6f, 1.8f, 4.8f));
            Vector3 bench = c + new Vector3(w / 4f, 0.25f, d / 2f - 1.5f);
            AK("concrete").Box(bench, new Vector3(4f, 0.5f, 0.7f), Quaternion.identity, 2f, 2f);
            AkBox(bench, new Vector3(4f, 0.5f, 0.7f));
            Rail("Bench", new[] { bench + new Vector3(-1.9f, 0.27f, 0.3f), bench + new Vector3(1.9f, 0.27f, 0.3f) }, false);
        }
        string name = (w <= 4f ? "Stepping stone" : AkIslandNames[kind]) + " " + index + " (" + c.y + "m)";
        return AkAddNode(name, NIsland, c.y, Rect.MinMaxRect(c.x - w / 2f, c.z - d / 2f, c.x + w / 2f, c.z + d / 2f));
    }

    static void LuckyCat(Vector3 at, float scale)
    {
        var k = new SkateMeshKit();
        Vector3 c = at;
        Color32 white = new Color32(250, 250, 250, 255), red = new Color32(230, 40, 50, 255), gold = new Color32(255, 210, 60, 255);
        float s = scale;
        k.Ellipsoid(c + Vector3.up * 2.4f * s, new Vector3(2.2f, 2.4f, 2f) * s, Quaternion.identity, 14, 10, white);
        k.Ellipsoid(c + Vector3.up * 5.4f * s, new Vector3(1.8f, 1.6f, 1.6f) * s, Quaternion.identity, 14, 10, white);
        foreach (var sx in new[] { -1f, 1f }) k.Cone(c + new Vector3(sx * 1.1f, 6.6f, 0f) * s, 0.6f * s, 0f, 1.2f * s, 6, white, 0f);
        k.Ellipsoid(c + new Vector3(1.6f, 6.4f, -0.4f) * s, new Vector3(0.5f, 1.2f, 0.5f) * s, Quaternion.Euler(0f, 0f, -15f), 8, 6, white);
        k.Box(c + new Vector3(0f, 4.2f, -1.7f) * s, new Vector3(2.4f, 0.4f, 0.3f) * s, Quaternion.identity, red);
        k.Ellipsoid(c + new Vector3(0f, 3.6f, -1.9f) * s, new Vector3(0.5f, 0.5f, 0.2f) * s, Quaternion.identity, 8, 6, gold);
        foreach (var sx in new[] { -0.6f, 0.6f }) k.Ellipsoid(c + new Vector3(sx, 5.6f, -1.5f) * s, new Vector3(0.25f, 0.12f, 0.1f) * s, Quaternion.identity, 6, 4, new Color32(30, 30, 30, 255));
        var mesh = k.Build("Lucky cat");
        SaveFeatureMesh(mesh);
        MeshObject("Lucky cat", akRoot, mesh, AkMat("white", ""), outlineMat);
        var col = new GameObject("Cat").AddComponent<CapsuleCollider>();
        col.transform.SetParent(akCol, false); col.transform.position = c + Vector3.up * 3.5f * s; col.radius = 2.1f * s; col.height = 7f * s;
    }

    // ---- glass lifts up the four towers ---------------------------------------------------------------------

    // (x, z, which tower): the lift's middle, beside the tower's front
    static readonly (float, float, float)[] AkLiftDefs = { (26.5f, -40f, 72f), (26.5f, 52f, 80f), (-26.5f, -40f, 64f), (-26.5f, 46f, 76f) };

    static void AkLifts()
    {
        foreach (var (x, z, h) in AkLiftDefs)
        {
            float side = Mathf.Sign(x);
            int roof = akNodes.FindIndex(nd => nd.kind == NRoof && Mathf.Abs(nd.top - h) < 0.1f && nd.Contains(new Vector2(side * (AkFront + 2f), z)));
            // the shaft: four posts and rings of frame, open on the street side and the tower side
            var k = AK("metal");
            foreach (var cx in new[] { -1.6f, 1.6f })
                foreach (var cz in new[] { -1.6f, 1.6f })
                {
                    Vector3 p = new Vector3(x + cx, 0f, z + cz);
                    AK("white", "e").Box(p + Vector3.up * (h + 3f) / 2f, new Vector3(0.16f, h + 3f, 0.16f), Quaternion.identity, 1f, 4f, new Color32(60, 170, 220, 255));
                    AkBox(p + Vector3.up * (h + 3f) / 2f, new Vector3(0.18f, h + 3f, 0.18f));
                }
            for (float y = 4f; y < h + 3f; y += 4f)
                foreach (var cz in new[] { -1.6f, 1.6f })
                    AK("white", "e").Box(new Vector3(x, y, z + cz), new Vector3(3.3f, 0.08f, 0.08f), Quaternion.identity, 1f, 1f, new Color32(80, 220, 255, 255));
            AK("metal").Box(new Vector3(x, h + 3.1f, z), new Vector3(3.6f, 0.3f, 3.6f), Quaternion.identity, 1f, 1f);
            // the car: a glass box open front and back, going up and down
            var go = new GameObject("Lift", typeof(Rigidbody), typeof(Mover), typeof(BoxCollider), typeof(MeshFilter), typeof(MeshRenderer));
            go.transform.SetParent(akRoot, false);
            go.GetComponent<Rigidbody>().isKinematic = true;
            var bc = go.GetComponent<BoxCollider>();
            bc.center = new Vector3(0f, -0.15f, 0f); bc.size = new Vector3(3f, 0.3f, 3f);
            var mk = new SkateMeshKit();
            mk.Box(new Vector3(0f, -0.15f, 0f), new Vector3(3f, 0.3f, 3f), Quaternion.identity, new Color32(70, 70, 90, 255));
            mk.Box(new Vector3(0f, 0.02f, 0f), new Vector3(2.8f, 0.04f, 2.8f), Quaternion.identity, new Color32(80, 220, 255, 255));
            foreach (var cz in new[] { -1.45f, 1.45f })
            {
                mk.Box(new Vector3(0f, 1.0f, cz), new Vector3(3f, 0.08f, 0.08f), Quaternion.identity, new Color32(200, 200, 215, 255));
                mk.Box(new Vector3(0f, 2.6f, cz), new Vector3(3f, 0.08f, 0.08f), Quaternion.identity, new Color32(200, 200, 215, 255));
            }
            var mesh = mk.Build("Lift");
            SaveFeatureMesh(mesh);
            go.GetComponent<MeshFilter>().sharedMesh = mesh;
            go.GetComponent<MeshRenderer>().sharedMaterials = new[] { AkMat("white", "e"), outlineMat };
            var m = go.GetComponent<Mover>();
            Vector3 bottom = new Vector3(x, Kerb + 0.08f, z), top = new Vector3(x, h + 0.02f, z);
            m.path = new[] { bottom, top };
            m.loop = false; m.speed = 9f; m.wait = 3f; m.easeIn = 5f; m.turn = false;
            go.transform.position = bottom;
            if (roof >= 0)
            {
                var l = AkAddLink("lift", 0, roof);
                l.start = bottom; l.forward = false; l.vehicle = m; l.alightAt = top;
                l.steerTo = new Vector3(side * (AkFront + 5f), h, z);
                l.timeout = 40f;
                Landing(l.steerTo);
            }
        }
    }

    // ---- escalators --------------------------------------------------------------------------------------------

    // (bottom, top, where it goes): up to the walkways, the plaza balconies, and one floating up to an island
    static readonly (Vector3, Vector3, string)[] AkEscalatorDefs = {
        (new Vector3(23.5f, Kerb, -45.9f), new Vector3(23.5f, AkWalkY, -58f), "south"),
        (new Vector3(-23.5f, Kerb, -45.9f), new Vector3(-23.5f, AkWalkY, -58f), "south"),
        (new Vector3(23.5f, Kerb, 104.1f), new Vector3(23.5f, AkWalkY, 92f), "north"),
        (new Vector3(-23.5f, Kerb, 44f), new Vector3(-23.5f, AkWalkY, 56f), "north"),
        (new Vector3(26.2f, Kerb, 24f), new Vector3(AkPlazaFront - 6f, AkBalconyY, 24f), "balcony e"),
        (new Vector3(-26.2f, Kerb, -24f), new Vector3(-(AkPlazaFront - 6f), AkBalconyY, -24f), "balcony w"),
        (new Vector3(-20f, Kerb, -46.5f), new Vector3(-20f, 14f, -22.5f), "island") };

    static void AkEscalators()
    {
        foreach (var (a, b, to) in AkEscalatorDefs)
        {
            int node = to == "south" ? akSouthWalk : to == "north" ? akNorthWalk : to == "balcony e" ? akBalconyE : to == "balcony w" ? akBalconyW : akIsland[5];
            Escalator(a, b, 2.2f, to == "island");
            Vector3 dir = FlatDir(b - a);
            Landing(b + dir * 2.5f);
            var l = AkAddLink("escalator", 0, node);
            l.start = a - dir * 3f; l.yaw = YawOf(dir);
        }
    }

    // a moving staircase from a up to b: the steps (scrolling, so they move), glass sides, handrails you can
    // grind, and if it's floating, a lattice under it
    static void Escalator(Vector3 a, Vector3 b, float width, bool floating)
    {
        Vector3 dir = FlatDir(b - a), side = Rt(dir) * (width / 2f);
        float run = Vector3.Distance(XZ(a), XZ(b)), rise = b.y - a.y, len = Vector3.Distance(a, b);
        float ang = Mathf.Atan2(rise, run) * Mathf.Rad2Deg;
        Quaternion q = Quaternion.LookRotation(dir) * Quaternion.Euler(-ang, 0f, 0f);
        var col = AddBox(akCol, "Escalator", (a + b) / 2f + q * Vector3.down * 0.15f, new Vector3(width, 0.3f, len), q);
        var esc = col.gameObject.AddComponent<Escalator>();
        esc.direction = (b - a).normalized; esc.speed = 5f;
        // a flat plate at the bottom to step on from
        Vector3 plate = a - dir * 0.8f + Vector3.up * 0.02f;
        AK("metal").Box(plate, new Vector3(width, 0.04f, 1.6f), Quaternion.LookRotation(dir), 1f, 1f, new Color32(200, 200, 210, 255));
        var k = AK("escalator", "x");
        k.Quad(a - side, b - side, b + side, a + side, new Vector2(0f, 0f), new Vector2(0f, len / 1.2f), new Vector2(width / 1.2f, len / 1.2f), new Vector2(width / 1.2f, 0f), Vector3.Cross(b - a, side));
        // the sides: a dark glass panel each side with a black handrail along the top (a rail)
        foreach (var sg in new[] { -1f, 1f })
        {
            Vector3 o = side * sg * 1.04f;
            AK("white").Quad(a + o, b + o, b + o + Vector3.up * 0.95f, a + o + Vector3.up * 0.95f, Vector2.zero, Vector2.up, Vector2.one, Vector2.right, side * sg, new Color32(40, 60, 90, 255));
            AK("white").Quad(a + o, b + o, b + o + Vector3.up * 0.95f, a + o + Vector3.up * 0.95f, Vector2.zero, Vector2.up, Vector2.one, Vector2.right, -side * sg, new Color32(40, 60, 90, 255));
            AK("white").Tube(new[] { a + o + Vector3.up * 1.0f - dir * 0.6f, a + o + Vector3.up * 1.0f, b + o + Vector3.up * 1.0f, b + o + Vector3.up * 1.0f + dir * 0.6f }, 0.06f, 6, 2f, new Color32(25, 25, 30, 255));
            Rail("Escalator handrail", new[] { a + o + Vector3.up * 1.05f, b + o + Vector3.up * 1.05f }, false);
            AkBox((a + b) / 2f + o + Vector3.up * 0.5f, new Vector3(0.1f, 1f, len), q);
            // the side skirt down to the floor (or the truss under a floating one)
            AK("metal").Quad(a + o, b + o, b + o + Vector3.down * 0.9f, a + o + Vector3.down * 0.3f, Vector2.zero, Vector2.up, Vector2.one, Vector2.right, side * sg, new Color32(150, 150, 165, 255));
        }
        AK("metal").Quad(a - side + Vector3.down * 0.3f, b - side + Vector3.down * 0.9f, b + side + Vector3.down * 0.9f, a + side + Vector3.down * 0.3f, Vector2.zero, Vector2.up, Vector2.one, Vector2.right, Vector3.down, new Color32(110, 110, 125, 255));
        if (floating)
        {
            // a glowing lattice under it, and nothing holding it up
            for (int i = 1; i < 8; i++)
            {
                Vector3 p0 = Vector3.Lerp(a, b, (i - 1) / 7f) + Vector3.down * 1f, p1 = Vector3.Lerp(a, b, i / 7f) + Vector3.down * 1f;
                foreach (var sg in new[] { -1f, 1f })
                    AK("white", "e").Cylinder(p0 + side * sg * 0.9f + Vector3.down * 0.6f, p1 + side * sg * 0.9f, 0.05f, 4, 2f, new Color32(255, 70, 190, 255));
            }
        }
    }

    // ---- stops: for the fast buses on the avenue, and the flying buses' stops on the plaza ----------------------

    static readonly Rect[] AkStopRects = {
        Rect.MinMaxRect(AkRoad + 0.4f, 12f, AkRoad + 3f, 24f), Rect.MinMaxRect(-AkRoad - 3f, -24f, -AkRoad - 0.4f, -12f),   // bus stops
        Rect.MinMaxRect(34f, -6f, 38f, 6f), Rect.MinMaxRect(-38f, -6f, -34f, 6f) };                                       // sky stops
    static readonly int[] akStop = new int[4];

    static void AkStops()
    {
        for (int i = 0; i < AkStopRects.Length; i++)
        {
            Rect r = AkStopRects[i];
            bool bus = i < 2;
            float s = Mathf.Sign(r.center.x);
            // the platform, with a shelter, and steps up at one end
            Vector3 c = new Vector3(r.center.x, (AkStopY + Kerb) / 2f, r.center.y);
            AK("concrete").Box(c, new Vector3(r.width, AkStopY - Kerb, r.height), Quaternion.identity, 3f, 3f);
            foreach (var sx in new[] { -1f, 1f })
                AK("posters", "e").Panel(new Vector3(sx > 0 ? r.xMax + 0.02f : r.xMin - 0.02f, c.y, r.center.y), Rt(new Vector3(sx, 0f, 0f)) * (r.height / 2f - 0.2f), Vector3.up * (AkStopY - Kerb) / 2f * 0.9f, null, false, new Rect(0f, 0f, r.height / 6f, 1f));
            AK("tactile").Ground(r.xMin + 0.1f, r.yMin, r.xMin + 0.7f, r.yMax, AkStopY + 0.01f, 0.6f, 20f);
            AK("tactile").Ground(r.xMax - 0.7f, r.yMin, r.xMax - 0.1f, r.yMax, AkStopY + 0.01f, 0.6f, 20f);
            AkBox(c, new Vector3(r.width, AkStopY - Kerb, r.height));
            float stepDir = bus ? (i == 0 ? 1f : -1f) : 1f;   // the steps go off this end (+z or -z)
            float endZ = stepDir > 0f ? r.yMax : r.yMin, run = 9.5f;
            Vector3 foot = new Vector3(r.center.x, Kerb, endZ + stepDir * run);
            float rise = AkStopY - Kerb, ang = Mathf.Atan2(rise, run) * Mathf.Rad2Deg;
            int steps = 11;
            for (int k = 0; k < steps; k++)
            {
                float hgt = rise * (steps - k) / steps, za = endZ + stepDir * run * k / steps, zb = endZ + stepDir * run * (k + 1) / steps;
                AK("concrete").Box(new Vector3(r.center.x, Kerb + hgt / 2f, (za + zb) / 2f), new Vector3(r.width, hgt, Mathf.Abs(zb - za)), Quaternion.identity, 3f, 3f);
            }
            Quaternion sq = Quaternion.LookRotation(new Vector3(0f, 0f, -stepDir)) * Quaternion.Euler(-ang, 0f, 0f);
            AkBox(new Vector3(r.center.x, Kerb + rise / 2f - 0.12f, endZ + stepDir * run / 2f), new Vector3(r.width, 0.3f, Mathf.Sqrt(run * run + rise * rise)), sq);
            // the shelter, on the side away from the road (or the bus)
            float back = bus ? (s > 0 ? r.xMax - 0.2f : r.xMin + 0.2f) : (s > 0 ? r.xMax - 0.2f : r.xMin + 0.2f);
            foreach (var z in new[] { r.yMin + 1f, r.yMax - 1f })
            {
                AK("metal").Box(new Vector3(back, AkStopY + 1.3f, z), new Vector3(0.15f, 2.6f, 0.15f), Quaternion.identity, 1f, 1f);
                AkBox(new Vector3(back, AkStopY + 1.3f, z), new Vector3(0.15f, 2.6f, 0.15f));
            }
            AK("metal").Box(new Vector3(back - s * 0.6f, AkStopY + 2.62f, r.center.y), new Vector3(1.6f, 0.1f, r.height - 1f), Quaternion.identity, 1f, 1f, new Color32(150, 150, 165, 255));
            AK("white", "e").Box(new Vector3(back - s * 1.38f, AkStopY + 2.62f, r.center.y), new Vector3(0.06f, 0.14f, r.height - 1f), Quaternion.identity, 1f, 1f, bus ? new Color32(60, 200, 120, 255) : new Color32(255, 70, 190, 255));
            AK("white").Box(new Vector3(back, AkStopY + 1.4f, r.center.y), new Vector3(0.06f, 2.2f, 5.2f), Quaternion.identity, 1f, 1f, new Color32(40, 40, 50, 255));
            foreach (var sx in new[] { -1f, 1f })
                AK("billboard_" + AI(0, 10), "e").Panel(new Vector3(back + sx * 0.04f, AkStopY + 1.4f, r.center.y), Rt(new Vector3(sx, 0f, 0f)) * 1.1f, Vector3.up * 1.05f);
            string name = bus ? "Bus stop " + (s > 0 ? "E" : "W") : "Sky stop " + (s > 0 ? "E" : "W");
            akStop[i] = AkAddNode(name, NStop, AkStopY, r);
            Landing(new Vector3(r.center.x, AkStopY, endZ - stepDir * 2f));
            var l = AkAddLink("steps", 0, akStop[i]);
            l.start = foot + new Vector3(0f, 0f, stepDir * 4f); l.yaw = stepDir > 0f ? 180f : 0f; l.sprint = true;
        }
    }

    // ---- skate stuff on the pavements and the plaza ---------------------------------------------------------

    static void AkStreetStuff()
    {
        // the plaza: a funbox, ledges, a couple of kickers, giant capsule toys that bounce you
        Funbox("Plaza funbox", Matrix4x4.TRS(new Vector3(-30f, Kerb, 14f), Quaternion.identity, Vector3.one), 3.2f);
        Funbox("Plaza funbox", Matrix4x4.TRS(new Vector3(30f, Kerb, -14f), Quaternion.LookRotation(Vector3.back), Vector3.one), 3.2f);
        foreach (var (p, yaw) in new[] { (new Vector3(-16f, Kerb, 26f), 0f), (new Vector3(18f, Kerb, -2f), 90f), (new Vector3(-36f, Kerb, -12f), 0f) })
        {
            Quaternion q = Quaternion.Euler(0f, yaw, 0f);
            Vector3 lc = p + Vector3.up * 0.3f;
            AK("concrete").Box(lc, new Vector3(0.8f, 0.6f, 7f), q, 2f, 2f);
            AkBox(lc, new Vector3(0.8f, 0.6f, 7f), q);
            Rail("Ledge", new[] { lc + q * new Vector3(0.32f, 0.32f, -3.3f), lc + q * new Vector3(0.32f, 0.32f, 3.3f) }, false);
        }
        Hump("Kicker", new Vector3(-14f, Kerb, -60f), Vector3.forward, 3.5f, 24f, 3f, RampSide2);
        Hump("Kicker", new Vector3(14f, Kerb, 74f), Vector3.back, 3.5f, 24f, 3f, RampSide2);
        foreach (var (p, r) in new[] { (new Vector3(-36f, Kerb, 24f), 1.7f), (new Vector3(36f, Kerb, 28f), 1.5f), (new Vector3(-12f, Kerb, 80f), 1.6f) })
            Capsule(p, r);
        // the guard rails along the kerbs (grindable), short bits with gaps
        foreach (var s in new[] { -1f, 1f })
            for (float z = -AkL + 14f; z < AkL - 12f; z += 26f)
            {
                if (Mathf.Abs(z) < AkPlazaHalf + 6f || Mathf.Abs(z - AkViaductZ) < 10f) continue;
                Rail("Guard rail", new[] { new Vector3(s * (AkRoad + 0.35f), Kerb + 0.75f, z), new Vector3(s * (AkRoad + 0.35f), Kerb + 0.75f, z + 12f) });
            }
    }

    // ---- traffic: fast buses (a kicker on the roof) and cars ------------------------------------------------

    static void AkTraffic()
    {
        Color32[] cols = { new Color32(255, 255, 255, 255), new Color32(40, 40, 50, 255), new Color32(255, 214, 40, 255), new Color32(220, 40, 60, 255), new Color32(60, 120, 220, 255) };
        foreach (var lane in new[] { AkLaneCar, AkLaneBus })
        {
            float end = AkL - 9f;
            var path = new[] { new Vector3(-lane, 0f, -end), new Vector3(-lane, 0f, end), new Vector3(lane, 0f, end), new Vector3(lane, 0f, -end) };
            float loop = end * 4f + lane * 4f;
            bool buses = lane > 4f;
            int n = buses ? 3 : 5;
            for (int i = 0; i < n; i++)
            {
                GameObject v;
                if (buses)
                {
                    v = Vehicle(akRoot, "Fast bus", 13f, 2.6f, 2.9f, new Color32(250, 250, 255, 255), new Color32(255, 70, 190, 255), true);
                    v.GetComponent<MeshRenderer>().sharedMaterials = new[] { AkMat("white", ""), outlineMat };
                    var side = new GameObject("Bus sides", typeof(MeshFilter), typeof(MeshRenderer));
                    side.transform.SetParent(v.transform, false);
                    var sk = new PSXKit();
                    foreach (var sx in new[] { -1f, 1f })
                        sk.Panel(new Vector3(sx * 1.32f, 2.05f, 0f), Rt(new Vector3(sx, 0f, 0f)) * 6.3f, Vector3.up * 1.2f, null, false, AkBusPhoto);
                    var sm = sk.Build("Bus sides");
                    SaveFeatureMesh(sm);
                    side.GetComponent<MeshFilter>().sharedMesh = sm;
                    side.GetComponent<MeshRenderer>().sharedMaterial = AkMat("photo_bus", "");
                    // a kicker on the front of the roof: ride forward along the roof and it throws you
                    var kick = new GameObject("Roof kicker", typeof(MeshFilter), typeof(MeshRenderer), typeof(MeshCollider));
                    kick.transform.SetParent(v.transform, false);
                    var kk = new SkateMeshKit();
                    float roofY = 0.38f + 2.9f + 0.2f, kz = 3.5f;
                    Vector3 a0 = new Vector3(-1f, roofY, kz), a1 = new Vector3(1f, roofY, kz), b0 = new Vector3(-1f, roofY + 0.9f, kz + 2.4f), b1 = new Vector3(1f, roofY + 0.9f, kz + 2.4f);
                    kk.Quad(a0, b0, b1, a1, Vector3.up + Vector3.back, new Color32(255, 214, 40, 255));
                    kk.Quad(b0, b0 + Vector3.down * 0.9f, b1 + Vector3.down * 0.9f, b1, Vector3.forward, new Color32(255, 70, 190, 255));
                    kk.Tri(a0, b0, b0 + Vector3.down * 0.9f, Vector3.left, new Color32(255, 70, 190, 255));
                    kk.Tri(a1, b1 + Vector3.down * 0.9f, b1, Vector3.right, new Color32(255, 70, 190, 255));
                    var km = kk.Build("Roof kicker");
                    SaveFeatureMesh(km);
                    kick.GetComponent<MeshFilter>().sharedMesh = km;
                    kick.GetComponent<MeshRenderer>().sharedMaterials = new[] { AkMat("white", ""), outlineMat };
                    kick.GetComponent<MeshCollider>().sharedMesh = km;
                }
                else
                {
                    v = Vehicle(akRoot, "Car", AR(4.4f, 5.2f), 1.9f, 1.6f, cols[i % cols.Length], new Color32(60, 180, 80, 255), false);
                    v.GetComponent<MeshRenderer>().sharedMaterials = new[] { AkMat("white", ""), outlineMat };
                }
                var m = v.GetComponent<Mover>();
                m.path = path; m.loop = true; m.speed = buses ? 16f : 9f; m.startAt = loop * i / n;
            }
        }
    }

    // ---- flying buses: slow, they stop at a sky stop, islands and a tower top; ride on the roof ------------------

    static void AkFlyingBuses()
    {
        // line A: the west sky stop, the pavement chunk, the rooftop chunk, the crown
        FlyingBusLine("Flying bus A", new[] { akStop[3], akIsland[5], akIsland[8], akIsland[10] },
            new[] { Dock(akStop[3], 1f, 0f), Dock(akIsland[5], -1f, -18f), Dock(akIsland[8], 1f, 10f), Dock(akIsland[10], -1f, -2f) },
            new Color32(255, 70, 190, 255));
        // line B: the east sky stop, the rooftop chunk by the plaza, the pavement chunk up north, the north-east tower
        int ne = akNodes.FindIndex(nd => nd.kind == NRoof && Mathf.Abs(nd.top - 80f) < 0.1f);
        FlyingBusLine("Flying bus B", new[] { akStop[2], akIsland[7], akIsland[11], ne },
            new[] { Dock(akStop[2], -1f, 0f), Dock(akIsland[7], 1f, 6f), Dock(akIsland[11], 1f, 34f), new Vector3(AkFront - 1.6f, 0f, 44f) },
            new Color32(60, 230, 255, 255));
    }

    // where a flying bus pulls up alongside a stop: on its east (+1) or west (-1) side, at z
    static Vector3 Dock(int node, float side, float z)
    {
        Rect r = akNodes[node].areas[0];
        return new Vector3(side > 0f ? r.xMax + 1.6f : r.xMin - 1.6f, 0f, z);
    }

    const float FlyBusRoof = 3f, FlyBusLen = 10f;
    static readonly Rect AkBusPhoto = new Rect(0.19f, 0.24f, 0.74f, 0.54f);   // just the bus's body in photo_bus (no background, no wheels)

    // a flying bus going back and forth between stops (docking alongside each, its roof level with the top)
    static void FlyingBusLine(string name, int[] stops, Vector3[] docks, Color32 col)
    {
        var path = new List<Vector3>();
        var at = new List<float>();
        float dist = 0f;
        System.Action<Vector3> add = p =>
        {
            if (path.Count > 0) dist += Vector3.Distance(path[path.Count - 1], p);
            path.Add(p);
        };
        Vector3 prev = Vector3.zero;
        for (int i = 0; i < stops.Length; i++)
        {
            Vector3 dock = new Vector3(docks[i].x, akNodes[stops[i]].top - FlyBusRoof, docks[i].z);
            if (i > 0)
            {
                // up (or down) to the next stop's height, across to just short of it, then in alongside it
                float y = Mathf.Max(prev.y, dock.y);
                if (y > prev.y + 0.1f) add(new Vector3(prev.x, y, prev.z));
                Vector3 approach = dock + new Vector3(0f, y - dock.y, dock.z > prev.z ? -8f : 8f);
                add(new Vector3(approach.x, y, approach.z));
                add(new Vector3(dock.x, y, dock.z));
                if (y > dock.y + 0.1f) add(dock);
            }
            else add(dock);
            at.Add(dist);
            prev = dock;
        }
        var go = new GameObject(name, typeof(Rigidbody), typeof(Mover), typeof(BoxCollider), typeof(MeshFilter), typeof(MeshRenderer));
        go.transform.SetParent(akRoot, false);
        go.GetComponent<Rigidbody>().isKinematic = true;
        var bc = go.GetComponent<BoxCollider>();
        bc.center = new Vector3(0f, (0.4f + FlyBusRoof) / 2f, 0f); bc.size = new Vector3(2.8f, FlyBusRoof - 0.4f, FlyBusLen);
        var k = new SkateMeshKit();
        k.Box(new Vector3(0f, (0.4f + FlyBusRoof) / 2f, 0f), new Vector3(2.8f, FlyBusRoof - 0.4f, FlyBusLen), Quaternion.identity, new Color32(245, 245, 250, 255));
        k.Box(new Vector3(0f, 1.9f, 0f), new Vector3(2.84f, 0.9f, FlyBusLen - 1.2f), Quaternion.identity, new Color32(120, 200, 255, 255));
        k.Box(new Vector3(0f, 0.9f, 0f), new Vector3(2.86f, 0.25f, FlyBusLen), Quaternion.identity, col);
        foreach (var e in new[] { -1f, 1f })
            k.Box(new Vector3(0f, FlyBusRoof + 0.02f, e * (FlyBusLen / 2f - 0.15f)), new Vector3(2.6f, 0.04f, 0.3f), Quaternion.identity, new Color32(255, 214, 40, 255));
        foreach (var sx in new[] { -1f, 1f })
            foreach (var sz in new[] { -3.4f, 3.4f })
            {
                k.Cylinder(new Vector3(sx * 1.1f, 0.4f, sz), new Vector3(sx * 1.1f, 0.15f, sz), 0.7f, 10, new Color32(60, 60, 80, 255));
                k.Cylinder(new Vector3(sx * 1.1f, 0.15f, sz), new Vector3(sx * 1.1f, 0.1f, sz), 0.55f, 10, col);
            }
        var mesh = k.Build(name);
        SaveFeatureMesh(mesh);
        go.GetComponent<MeshFilter>().sharedMesh = mesh;
        go.GetComponent<MeshRenderer>().sharedMaterials = new[] { AkMat("white", "e"), outlineMat };
        // photo sides, like the buses on the street
        var sides = new GameObject("Bus sides", typeof(MeshFilter), typeof(MeshRenderer));
        sides.transform.SetParent(go.transform, false);
        var sk = new PSXKit();
        foreach (var sx in new[] { -1f, 1f })
            sk.Panel(new Vector3(sx * 1.43f, 1.75f, 0f), Rt(new Vector3(sx, 0f, 0f)) * (FlyBusLen / 2f - 0.3f), Vector3.up * 1.1f, null, false, AkBusPhoto);
        var sm = sk.Build(name + " sides");
        SaveFeatureMesh(sm);
        sides.GetComponent<MeshFilter>().sharedMesh = sm;
        sides.GetComponent<MeshRenderer>().sharedMaterial = AkMat("photo_bus", "e");
        var m = go.GetComponent<Mover>();
        m.path = path.ToArray(); m.loop = false; m.speed = 6f; m.wait = 4f; m.easeIn = 6f;
        m.stops = at.GetRange(1, at.Count - 2).ToArray();
        go.transform.position = path[0];
        // a link for each hop along the line (both ways)
        for (int i = 0; i + 1 < stops.Length; i++)
        {
            var l = AkAddLink("flying bus", stops[i], stops[i + 1]);
            Vector3 d0 = new Vector3(docks[i].x, akNodes[stops[i]].top, docks[i].z), d1 = new Vector3(docks[i + 1].x, akNodes[stops[i + 1]].top, docks[i + 1].z);
            l.start = d0; l.forward = false; l.vehicle = m;
            l.alightAt = d1 + Vector3.down * FlyBusRoof;
            l.steerTo = NodePoint(akNodes[stops[i + 1]], XZ(d1), 2.5f, false);
            Landing(l.steerTo);
            l.timeout = 90f;
            l.vehicleFrom = at[i];
        }
    }

    // ---- flying cars, parked about: land on one and fly it ---------------------------------------------------

    static void AkFlyingCars()
    {
        Color32[] cols = { new Color32(255, 230, 60, 255), new Color32(255, 80, 200, 255), new Color32(60, 230, 255, 255), new Color32(255, 140, 40, 255) };
        var spots = new List<(Vector3, float, int, int)> {
            (new Vector3(34f, Kerb, -24f), 0f, 0, akIsland[7]),          // on the plaza: fly it up to the rooftop chunk
            (new Vector3(-16f, Kerb, -100f), 0f, 0, -1),
            (new Vector3(16f, Kerb, 84f), 180f, 0, -1),
            (akNodes[akIsland[6]].Centre + new Vector3(3f, 0f, 3f), 90f, akIsland[6], -1),
            (akNodes[akIsland[10]].Centre + new Vector3(-3f, 0f, 3f), 0f, akIsland[10], -1),
            (new Vector3(-AkFront - 6f, 34f, 78f), 0f, -1, -1) };
        int ne = akNodes.FindIndex(nd => nd.kind == NRoof && Mathf.Abs(nd.top - 80f) < 0.1f);
        spots[4] = (spots[4].Item1, spots[4].Item2, spots[4].Item3, ne);   // from the crown up to the north-east tower
        int i = 0;
        foreach (var (at, yaw, from, to) in spots)
        {
            var go = new GameObject("Flying car", typeof(Rigidbody), typeof(HoverCar), typeof(MeshCollider), typeof(MeshFilter), typeof(MeshRenderer));
            go.transform.SetParent(akRoot, false);
            go.transform.SetPositionAndRotation(at + Vector3.up * 0.05f, Quaternion.Euler(0f, yaw, 0f));
            go.GetComponent<Rigidbody>().isKinematic = true;
            var mesh = HoverMesh("Flying car", cols[i++ % cols.Length]);
            go.GetComponent<MeshFilter>().sharedMesh = mesh;
            go.GetComponent<MeshRenderer>().sharedMaterials = new[] { AkMat("white", "e"), outlineMat };
            go.GetComponent<MeshCollider>().sharedMesh = mesh;
            var hc = go.GetComponent<HoverCar>();
            hc.climb = 60f; hc.fuse = 5f;
            hc.seat = new Vector3(0f, 1.3f, 0f);
            hc.fire = Burst(go.transform, "Explosion", new Color(1f, 0.55f, 0.1f), new Color(1f, 0.95f, 0.4f), 1.2f, 3.5f, 14f, 26f, 0.7f, 120);
            hc.smoke = Burst(go.transform, "Smoke", new Color(0.25f, 0.2f, 0.3f, 0.8f), new Color(0.5f, 0.45f, 0.55f, 0.6f), 2.5f, 5f, 3f, 8f, 2.2f, 40);
            Use(at, 3f);
            if (to >= 0)
            {
                var l = AkAddLink("flying car", from < 0 ? 0 : from, to);
                l.start = at + Vector3.up * 1.6f; l.forward = false; l.car = hc;
                l.steerTo = akNodes[to].Centre;
                l.yaw = yaw;
            }
        }
    }

    // a low, sleek flying car: its roof is low enough to jump onto
    static Mesh HoverMesh(string name, Color32 body)
    {
        var k = new SkateMeshKit();
        k.Box(new Vector3(0f, 0.6f, 0f), new Vector3(2.3f, 0.6f, 4.4f), Quaternion.identity, body);
        k.Box(new Vector3(0f, 1.05f, -0.2f), new Vector3(2.0f, 0.32f, 2.4f), Quaternion.identity, new Color32(80, 200, 255, 255));
        k.Box(new Vector3(0f, 1.23f, -0.2f), new Vector3(2.0f, 0.04f, 2.4f), Quaternion.identity, body);
        k.Box(new Vector3(0f, 0.65f, 2.21f), new Vector3(1.8f, 0.18f, 0.04f), Quaternion.identity, new Color32(255, 250, 220, 255));
        k.Box(new Vector3(0f, 0.65f, -2.21f), new Vector3(1.8f, 0.18f, 0.04f), Quaternion.identity, new Color32(255, 40, 60, 255));
        foreach (var sx in new[] { -1.25f, 1.25f })
            foreach (var sz in new[] { -1.5f, 1.5f })
            {
                k.Cylinder(new Vector3(sx, 0.32f, sz), new Vector3(sx, 0.2f, sz), 0.5f, 10, new Color32(60, 60, 80, 255));
                k.Cylinder(new Vector3(sx, 0.2f, sz), new Vector3(sx, 0.17f, sz), 0.4f, 10, new Color32(255, 80, 200, 255));
            }
        var mesh = k.Build(name);
        SaveFeatureMesh(mesh);
        return mesh;
    }

    // a trampoline set into the ground: ride onto it and it throws you straight up
    static void Trampoline(Vector3 at, Vector3 facing, float speed)
    {
        Color32 mat = new Color32(60, 230, 255, 255);
        AK("metal").Cylinder(at, at + Vector3.up * 0.12f, 1.5f, 12, 2f, new Color32(60, 50, 80, 255));
        AK("white", "e").Cylinder(at + Vector3.up * 0.12f, at + Vector3.up * 0.13f, 1.3f, 12, 2f, mat);
        AK("white", "e").Cylinder(at + Vector3.up * 0.13f, at + Vector3.up * 0.14f, 0.6f, 12, 2f, new Color32(255, 255, 255, 255));
        var col = AddBox(akCol, "Trampoline", at + Vector3.up * 0.06f, new Vector3(2.6f, 0.12f, 2.6f), Quaternion.LookRotation(facing));
        col.gameObject.AddComponent<Bouncer>().speed = speed;
    }

    // ---- the skyline round the outside -------------------------------------------------------------------

    static void AkBackdrop()
    {
        var rnd = new System.Random(77);
        System.Func<float, float, float> R = (a, b) => a + (float)rnd.NextDouble() * (b - a);
        foreach (var s in new[] { -1f, 1f })
        {
            // along the sides, past the alleys
            for (float z = -AkL - 60f; z < AkL + 60f; z += R(18f, 30f))
            {
                float w = R(16f, 28f), d = R(20f, 40f), h = R(50f, 140f);
                Vector3 c = new Vector3(s * (AkBack + 10f + d / 2f), h / 2f, z + w / 2f);
                AK("fac_tower_" + rnd.Next(0, 4)).Box(c, new Vector3(d, h, w), Quaternion.identity, 16f, 21f);
            }
            // across the ends, past the end buildings
            for (float x = -AkBack - 40f; x < AkBack + 40f; x += R(18f, 30f))
            {
                float w = R(16f, 28f), d = R(20f, 40f), h = R(60f, 150f);
                Vector3 c = new Vector3(x + w / 2f, h / 2f, s * (AkL + 38f + d / 2f));
                AK("fac_tower_" + rnd.Next(0, 4)).Box(c, new Vector3(w, h, d), Quaternion.identity, 16f, 21f);
            }
        }
        // a blimp going round, high up
        var blimp = new GameObject("Blimp", typeof(Rigidbody), typeof(Mover));
        blimp.transform.SetParent(akRoot, false);
        blimp.GetComponent<Rigidbody>().isKinematic = true;
        var bk = new SkateMeshKit();
        bk.Ellipsoid(Vector3.zero, new Vector3(7f, 7f, 22f), Quaternion.identity, 16, 10, new Color32(240, 240, 250, 255));
        bk.Box(new Vector3(0f, -7.5f, 0f), new Vector3(2.5f, 2f, 6f), Quaternion.identity, new Color32(80, 80, 100, 255));
        foreach (var f in new[] { Quaternion.identity, Quaternion.Euler(0f, 0f, 90f) })
            bk.Box(new Vector3(0f, 0f, -19f), f * new Vector3(0.3f, 9f, 5f), f, new Color32(255, 70, 160, 255));
        var bm = bk.Build("Blimp");
        SaveFeatureMesh(bm);
        blimp.AddComponent<MeshFilter>().sharedMesh = bm;
        blimp.AddComponent<MeshRenderer>().sharedMaterials = new[] { AkMat("white", ""), outlineMat };
        var bp = new List<Vector3>();
        for (int i = 0; i < 16; i++) { float a = i * Mathf.PI * 2f / 16; bp.Add(new Vector3(Mathf.Cos(a) * 140f, 160f, Mathf.Sin(a) * 220f)); }
        var bmv = blimp.GetComponent<Mover>();
        bmv.path = bp.ToArray(); bmv.loop = true; bmv.speed = 8f;
    }

